fn fresh_state(card_id: CardId, base_damage: i32, base_block: i32) -> (CombatState, CreatureUid) {
    let mut state = CombatState {
        rng: sts2_core::dotnet_rng::Rng::new(0_i32),
        ..Default::default()
    };
    // Alive player -- a dead one trips the C# IsOverOrEnding select guard
    // in request_card_choice.
    state.player.current_hp = 80;
    state.player.max_hp = 80;
    let enemy_id = NonZeroU32::new(1).expect("nz");
    state.creatures.push(Creature {
        id: enemy_id,
        current_hp: 100,
        max_hp: 100,
        block: 0,
        powers: SmallVec::new(),
        species: Some(MonsterKind::Nibbit),
        intent: None,
        intent_history: IntentHistory::default(),
        monster_id: MonsterId("Nibbit"),
        ai: None,
    });
    let euid = CreatureUid(enemy_id);
    state.enemy_uids.push(euid);
    // Push a card POD into the store; its UID == 1 (1-based).
    let card_uid = NonZeroU32::new(1).expect("nz");
    state.cards.push(Card {
        uid: sts2_core::CardUid(card_uid),
        card_id,
        cost: 1,
        card_type: CardType::Attack,
        target_type: TargetType::Enemy,
        upgraded: false,
        base_damage,
        base_block,
        ..Card::pod_defaults()
    });
    state.player.play.push(sts2_core::CardUid(card_uid));
    (state, euid)
}

#[test]
fn silent_power_amounts_scale_with_upgrade() {
    // C# OnUpgrade bumps these power/debuff amounts. Bead qplr9.
    install_pool();
    let player_power = |card: CardId, kind: PowerKind, upgraded: bool| -> Option<i32> {
        let (mut state, euid) = fresh_state(card, 6, 0);
        state.cards[0].upgraded = upgraded;
        let _ = lookup(card).expect("registered")(&mut state, Some(euid));
        state.player.powers.iter().find_map(|pu| {
            state
                .powers
                .iter()
                .find(|p| p.id == pu.0 && p.kind == kind)
                .map(|p| p.amount)
        })
    };
    let enemy_power = |card: CardId, kind: PowerKind, upgraded: bool| -> Option<i32> {
        let (mut state, euid) = fresh_state(card, 6, 0);
        state.cards[0].upgraded = upgraded;
        let _ = lookup(card).expect("registered")(&mut state, Some(euid));
        state.creatures[0].powers.iter().find_map(|pu| {
            state
                .powers
                .iter()
                .find(|p| p.id == pu.0 && p.kind == kind)
                .map(|p| p.amount)
        })
    };
    for (card, kind, base, up) in [
        // Bead `sts2-rs-zwi53`: C# applies AnticipatePower, not Dexterity.
        (CardId::Anticipate, PowerKind::Anticipate, 2, 3),
        (CardId::AccuracyCard, PowerKind::Accuracy, 4, 6),
        (CardId::NoxiousFumesCard, PowerKind::NoxiousFumes, 2, 3),
        (CardId::OutbreakCard, PowerKind::Outbreak, 11, 15),
        (CardId::Abrasive, PowerKind::Thorns, 4, 6),
        // sts2-rs-14gx2: upgrade-scaling power amounts.
        // (BladeOfInk no longer grants a self-power — it generates 2/3 Shivs
        // into hand per the C# decomp; see `blade_of_ink_generates_shivs`.)
        (CardId::SerpentFormCard, PowerKind::SerpentForm, 4, 6),
        (CardId::EnvenomCard, PowerKind::Envenom, 1, 2),
        (CardId::Burst, PowerKind::Burst, 1, 2),
        (CardId::Accelerant, PowerKind::Accelerant, 1, 2),
    ] {
        assert_eq!(player_power(card, kind, false), Some(base), "{kind:?} base");
        assert_eq!(
            player_power(card, kind, true),
            Some(up),
            "{kind:?} upgraded"
        );
    }
    for (card, kind, base, up) in [
        (CardId::DeadlyPoison, PowerKind::Poison, 5, 7),
        (CardId::PoisonedStab, PowerKind::Poison, 3, 4),
        (CardId::Expose, PowerKind::Vulnerable, 2, 3),
        (CardId::Strangle, PowerKind::Strangle, 2, 3),
        // Bead `sts2-rs-wwr0b`: Assassinate Vulnerable 1 / upgrade 2.
        (CardId::Assassinate, PowerKind::Vulnerable, 1, 2),
        // BubbleBubble is gated on an already-poisoned target (bead
        // `sts2-rs-ihpq0`), so it cannot be exercised by the
        // fresh-enemy helper above. Its 9 → 12 scaling + gate is
        // pinned in `bubble_bubble_gates_on_already_poisoned_target`.
    ] {
        assert_eq!(enemy_power(card, kind, false), Some(base), "{kind:?} base");
        assert_eq!(enemy_power(card, kind, true), Some(up), "{kind:?} upgraded");
    }
}

/// Bead `sts2-rs-ihpq0`: C# `BubbleBubble.OnPlay` only applies Poison
/// when the chosen target *already* has Poison, and the amount scales
/// 9 → 12 on upgrade. A fresh (un-poisoned) enemy must remain a no-op.
#[test]
fn bubble_bubble_gates_on_already_poisoned_target() {
    install_pool();
    // No pre-existing Poison: the gate fails and the card is a no-op.
    {
        let (mut state, euid) = fresh_state(CardId::BubbleBubble, 6, 0);
        let _ = lookup(CardId::BubbleBubble).expect("registered")(&mut state, Some(euid));
        assert_eq!(
            power_amount_on_creature(&state, euid, PowerKind::Poison),
            0,
            "BubbleBubble must be a no-op on an un-poisoned target"
        );
    }
    // Already-poisoned target: base adds 9 (1 seed + 9 = 10).
    {
        let (mut state, euid) = fresh_state(CardId::BubbleBubble, 6, 0);
        apply_power_to_enemy(&mut state, euid, PowerKind::Poison, 1);
        let _ = lookup(CardId::BubbleBubble).expect("registered")(&mut state, Some(euid));
        assert_eq!(
            power_amount_on_creature(&state, euid, PowerKind::Poison),
            1 + 9,
            "BubbleBubble base adds 9 Poison to an already-poisoned target"
        );
    }
    // Upgraded already-poisoned target: adds 12 (1 seed + 12 = 13).
    {
        let (mut state, euid) = fresh_state(CardId::BubbleBubble, 6, 0);
        state.cards[0].upgraded = true;
        apply_power_to_enemy(&mut state, euid, PowerKind::Poison, 1);
        let _ = lookup(CardId::BubbleBubble).expect("registered")(&mut state, Some(euid));
        assert_eq!(
            power_amount_on_creature(&state, euid, PowerKind::Poison),
            1 + 12,
            "upgraded BubbleBubble adds 12 Poison to an already-poisoned target"
        );
    }
}

/// Macro: ensures `install_pool` registers a handler for the given CardId.
macro_rules! pin_registered {
    ($name:ident, $variant:ident) => {
        #[test]
        fn $name() {
            install_pool();
            assert!(
                lookup(CardId::$variant).is_some(),
                concat!("CardId::", stringify!($variant), " has no handler")
            );
        }
    };
}

