/// `sts2-rs-ai23c`: upgraded Expertise targets 7 cards in hand (not 6).
#[test]
fn ai23c_expertise_upgraded_draws_to_seven() {
    install_pool();
    // Seed an empty-hand state with at least 7 cards in draw so the
    // draw can satisfy the upgraded target.
    let (mut state, _euid) = fresh_state(CardId::Expertise, 0, 0);
    state.cards[0].upgraded = true;
    for _ in 0..7_u32 {
        let raw = u32::try_from(state.cards.len() + 1).expect("fits");
        let uid = sts2_core::CardUid::new(raw).expect("non-zero");
        state.cards.push(Card {
            uid,
            card_id: CardId::Wound,
            cost: 1,
            card_type: CardType::Status,
            target_type: TargetType::Self_,
            upgraded: false,
            base_damage: 0,
            base_block: 0,
            ..Card::pod_defaults()
        });
        state.player.draw.push(uid);
    }
    let _ = lookup(CardId::Expertise).expect("registered")(&mut state, None);
    assert_eq!(state.player.hand.len(), 7, "upgraded Expertise draws to 7");
}

