/// Bead `sts2-rs-txm8`: Finisher with NO prior Attacks lands a
/// Bead `sts2-rs-nucbp`: C# Finisher with NO prior Attack
/// plays this turn deals ZERO damage (`WithHitCount(0)`); the
/// prior Rust port floored output at 1 hit, matching Python's
/// `max(1, ...)` fallback but not C#.
#[test]
fn nucbp_finisher_with_no_prior_attacks_deals_zero_damage() {
    install_pool();
    let (mut state, euid) = fresh_state(CardId::Finisher, 6, 0);
    let hp_before = state.creatures[0].current_hp;
    let f = lookup(CardId::Finisher).expect("registered");
    let r = f(&mut state, Some(euid));
    assert_eq!(r, EffectResult::Resolved);
    assert_eq!(
        state.creatures[0].current_hp, hp_before,
        "Finisher with 0 prior attacks deals 0 hits = 0 damage (C# WithHitCount(0))",
    );
}

/// Bead `sts2-rs-nucbp`: Finisher hits = prior Attack plays
/// this turn (NOT +1). After 2 prior Attack plays, Finisher
/// lands 2 hits × 5 dmg = 10 → HP 100 → 90. The prior Rust
/// port asserted 3 hits, which over-counted by one Finisher
/// self-hit not present in C# `History.CardPlaysFinished`.
#[test]
fn nucbp_finisher_hits_equal_prior_attacks_this_turn() {
    install_pool();
    let (mut state, euid) = fresh_state(CardId::Finisher, 5, 0);
    let atk_idx = CardType::Attack.index();
    state.player.cards_played_this_turn[atk_idx] = 2;
    let f = lookup(CardId::Finisher).expect("registered");
    let r = f(&mut state, Some(euid));
    assert_eq!(r, EffectResult::Resolved);
    assert_eq!(
        state.creatures[0].current_hp, 90,
        "2 hits × 5 dmg = 10 → 100-10=90 (prior +1 self-hit removed)",
    );
}

/// Scare (v0.107.1 rename+rework of FollowThrough). C# `Scare.OnPlay`
/// applies 1 Weak to every hittable enemy — no damage. Bead
/// `sts2-rs-v0107-content-port-wb8lk.5`.
#[test]
fn scare_applies_weak_one_to_all_enemies() {
    install_pool();
    let (mut state, euid) = fresh_state(CardId::Scare, 0, 0);
    // A second enemy: Scare is AllEnemies, so both must receive Weak.
    let enemy2 = NonZeroU32::new(2).expect("nz");
    state.creatures.push(Creature {
        id: enemy2,
        current_hp: 100,
        max_hp: 100,
        block: 0,
        powers: SmallVec::new(),
        species: Some(MonsterKind::Nibbit),
        intent: None,
        intent_history: IntentHistory::default(),
        monster_id: MonsterId("Nibbit"),
        ai: None,
    });
    let euid2 = CreatureUid(enemy2);
    state.enemy_uids.push(euid2);

    let f = lookup(CardId::Scare).expect("registered");
    let r = f(&mut state, Some(euid));
    assert_eq!(r, EffectResult::Resolved);
    assert_eq!(
        power_amount_on_creature(&state, euid, PowerKind::Weak),
        1,
        "Scare applies 1 Weak to the first enemy",
    );
    assert_eq!(
        power_amount_on_creature(&state, euid2, PowerKind::Weak),
        1,
        "Scare applies 1 Weak to every enemy (AllEnemies)",
    );
    // No damage component.
    assert_eq!(state.creatures[0].current_hp, 100, "Scare deals no damage");
}

/// Scare is a 0-cost Uncommon Skill with Exhaust; upgrading removes the
/// Exhaust keyword (C# `OnUpgrade RemoveKeyword(Exhaust)`), no value change.
#[test]
fn scare_spec_and_upgrade_drops_exhaust() {
    let s = scare::spec();
    assert_eq!(s.cost, 0);
    assert_eq!(s.card_type, CardType::Skill);
    assert_eq!(s.target_type, TargetType::AllEnemies);
    assert_eq!(s.rarity, CardRarity::Uncommon);
    assert!(
        s.keywords.contains(CardKeywords::EXHAUST),
        "base Scare has Exhaust",
    );
    let delta = scare::upgrade().expect("Scare upgrades");
    assert_eq!(
        delta.keywords,
        Some(CardKeywords::NONE),
        "upgraded Scare drops Exhaust (empty keyword set)",
    );
    assert_eq!(delta.base_damage, None);
    assert_eq!(delta.cost, None);
}

/// Bead `sts2-rs-nucbp` (was `sts2-rs-txm8`): only Attack-typed
/// plays scale Finisher's hit count. With 1 Skill + 1 Power but
/// 0 Attacks played this turn, Finisher lands 0 hits (C# `WithHitCount(0)`).
#[test]
fn finisher_ignores_skill_plays_this_turn() {
    install_pool();
    let (mut state, euid) = fresh_state(CardId::Finisher, 4, 0);
    state.player.cards_played_this_turn[CardType::Skill.index()] = 1;
    state.player.cards_played_this_turn[CardType::Power.index()] = 1;
    let hp_before = state.creatures[0].current_hp;
    let f = lookup(CardId::Finisher).expect("registered");
    let _ = f(&mut state, Some(euid));
    assert_eq!(
        state.creatures[0].current_hp, hp_before,
        "Skills/Powers don't count as Attacks → 0 hits = 0 damage",
    );
}

