/// Bead `sts2-rs-1rwuh`: C# `Expose.OnPlay` strips the target's
/// block to 0 (via `CreatureCmd.LoseBlock(target, target.Block)`),
/// then applies Vulnerable(2). The card itself does NO damage —
/// CanonicalVars carry only `Var("Power", 2m)`. The earlier Rust
/// body fired `deal_damage_player_to_enemy(t, 0)` (no-op because
/// `base_damage = 0` in the spec) and skipped LoseBlock entirely.
#[test]
fn play_expose_strips_block_and_applies_vulnerable() {
    install_pool();
    let (mut state, euid) = fresh_state(CardId::Expose, 0, 0);
    // Seed the target with block; Expose must strip it to 0.
    if let Some(idx) = state.creatures.iter().position(|c| c.id == euid.0) {
        state.creatures[idx].block = 9;
    }
    let f = lookup(CardId::Expose).expect("registered");
    f(&mut state, Some(euid));
    let target_block = state
        .creatures
        .iter()
        .find(|c| c.id == euid.0)
        .map_or(-1, |c| c.block);
    assert_eq!(target_block, 0, "Expose strips the target's block");
    let v = state
        .powers
        .iter()
        .find(|p| p.kind == PowerKind::Vulnerable)
        .expect("Vulnerable applied");
    assert_eq!(v.amount, 2);
    // No HP change — Expose deals NO damage in C#.
    let target_hp = state
        .creatures
        .iter()
        .find(|c| c.id == euid.0)
        .map_or(-1, |c| c.current_hp);
    assert_eq!(target_hp, 100, "Expose deals no damage");
}

