/// Issue #175 (Silent combat parity, v0.107.1): `Dash.OnPlay`
/// (`MegaCrit.Sts2.Core.Models.Cards/Dash.cs:30-33`) gains block FIRST
/// (`CreatureCmd.GainBlock`), THEN executes the attack (`DamageCmd.Attack`).
/// The order is load-bearing against a Thorns enemy: the player must already
/// hold Dash's block before the targeted attack fires, so the enemy's Thorns
/// retaliation is absorbed by that block instead of landing on bare HP.
///
/// Repro seed 197 (Spiny Toad's PROTRUDING_SPIKES_MOVE grants the toad
/// Thorns(5) by the player's turn 1): DASH+1 (13 dmg / 13 block) — C# leaves
/// the player at block 8, HP unchanged; the old Rust order (damage then block)
/// took 5 HP and kept block 13.
#[test]
fn play_dash_gains_block_before_attack_absorbs_thorns() {
    install_pool();
    // DASH+1: base_damage 13, base_block 13.
    let (mut state, euid) = fresh_state(CardId::Dash, 13, 13);
    state.cards[0].upgraded = true;
    state.player.current_hp = 70;
    state.player.max_hp = 70;
    // Seed the targeted enemy with Thorns(5), as the Spiny Toad holds by
    // the player's first turn.
    let sid = NonZeroU32::new(900).expect("nz");
    state.powers.push(Power {
        id: sid,
        kind: PowerKind::Thorns,
        amount: 5,
        counter: 0,
        applier: None,
        skip_next_tick: false,
    });
    state.creatures[0].powers.push(PowerUid(sid));

    let f = lookup(CardId::Dash).expect("registered");
    let _ = f(&mut state, Some(euid));

    // Block gained (13) BEFORE the attack, so the 5 Thorns retaliation is
    // absorbed: block 13 - 5 = 8, player HP untouched at 70.
    assert_eq!(state.player.block, 8, "Dash block (13) absorbs Thorns(5)");
    assert_eq!(
        state.player.current_hp, 70,
        "Thorns retaliation absorbed by block — no HP loss",
    );
    // Enemy took Dash's 13 damage (100 - 13 = 87).
    assert_eq!(state.creatures[0].current_hp, 87, "Dash deals 13 to target");
}

