/// **Bead `sts2-rs-zlx.2` (zlx-b)**: After Abrasive resolves, the
/// player carries Thorns(4); a powered enemy attack should fire the
/// `before_damage_received` listener (wired by `sts2-rs-3to`) and
/// reflect 4 HP-loss back at the attacker. End-to-end integration
/// test for the "on-attack-received reactive" path the bead asked
/// for — proves the existing bus + Thorns arm is reachable from
/// card play.
#[test]
fn abrasive_grants_thorns_reflects_on_attack_received() {
    use sts2_core::hooks::{collect_before_damage_received, CreatureRef, DamageCtx, ValueProps};
    install_pool();
    let (mut state, euid) = fresh_state(CardId::Abrasive, 0, 0);
    // Bead `sts2-rs-4zxc0`: seed player HP before init so the
    // post-au4l2 `apply_power_to_creature` path (which gates on
    // `current_hp > 0`) accepts the player creature.
    state.player.current_hp = 70;
    state.player.max_hp = 70;
    // Wire the player creature so CreatureRef::Player resolves.
    let _ = state.init_player_creature();
    let f = lookup(CardId::Abrasive).expect("registered");
    let _ = f(&mut state, None);
    // Simulate an enemy powered attack on the player.
    let ctx = DamageCtx {
        dealer: CreatureRef::Enemy(euid),
        target: CreatureRef::Player,
        props: ValueProps::MOVE,
    };
    let effects = collect_before_damage_received(&state, &ctx);
    // Exactly one DealHpLoss back at the attacker for 4 damage,
    // carrying UNPOWERED | SKIP_HURT_ANIM (the Thorns reflective shape).
    assert_eq!(effects.len(), 1, "expected 1 reflective effect from Thorns");
    match effects[0] {
        sts2_core::hooks::Effect::DealHpLoss {
            amount,
            props,
            target,
            ..
        } => {
            assert_eq!(amount, 4, "Thorns reflects 4 = power.amount");
            assert!(props.contains(ValueProps::UNPOWERED));
            assert!(props.contains(ValueProps::SKIP_HURT_ANIM));
            assert!(matches!(target, CreatureRef::Enemy(_)));
        }
        ref other => panic!("expected DealHpLoss, got {other:?}"),
    }
}

