// ---- G3 plumbing: stack-based retain semantics (bead `sts2-rs-sah`) ----
//
// Two tests cover the new retain plumbing:
//
//   * `tactician_grants_energy_no_self_retain` — STS2 Tactician
//     is +1 energy on play (Python `silent.py:594-596`). It does
//     NOT retain itself (no `retain` keyword on the card; only
//     `sly`). This pins the real-body energy gain and the
//     non-retain invariant.
//
//   * `well_laid_plans_retains_one_card_at_end_of_turn` — Full
//     end-to-end: playing WellLaidPlans applies the power; the
//     end-of-turn retain-compute step accumulates the power's
//     amount into the budget; one hand card survives the flush.
//
/// Tactician (STS2) gives +1 energy on play. No retain side effect.
#[test]
fn tactician_grants_energy_no_self_retain() {
    install_pool();
    let s = crate::cards::silent::tactician::spec();
    assert_eq!(s.cost, 3, "Tactician costs 3 (Python pin)");
    assert_eq!(s.card_type, CardType::Skill);
    let f = lookup(CardId::Tactician).expect("registered");
    let (mut state, _) = fresh_state(CardId::Tactician, 0, 0);
    let energy_before = state.player.energy;
    let r = f(&mut state, None);
    assert_eq!(r, EffectResult::Resolved);
    assert_eq!(
        state.player.energy,
        energy_before.saturating_add(1),
        "Tactician grants +1 energy"
    );
    // No retain side-table mutation: Tactician is `sly`, not `retain`.
    assert!(
        state.player.retain_this_turn.is_empty(),
        "Tactician must not flag retain"
    );
    assert_eq!(
        state.player.pending_retain_count, 0,
        "Tactician must not grant retain budget"
    );
    assert!(
        state.powers.is_empty(),
        "Tactician applies no powers (real-body is energy-only)"
    );
}

/// Well-Laid Plans on play applies the WellLaidPlans power.
/// At end-of-turn the power surfaces an INTERACTIVE `RetainAtTurnEnd`
/// card-select (C# `WellLaidPlansPower.BeforeFlushLate`,
/// WellLaidPlansPower.cs:19-39): `min_select=0`, `max_select=Amount`,
/// options = hand cards not already retaining. Resolving the select with
/// the decoy retains exactly that card for the turn; the rest of the hand
/// flushes. Bead `sts2-rs-wlp-retain-select`.
#[test]
fn well_laid_plans_retains_one_card_at_end_of_turn() {
    use sts2_core::combat_loop::{end_player_turn_phase_one, end_player_turn_phase_two};
    use sts2_core::{Action, CardUid, ChoiceKind, CombatPhase, StepResult};
    install_pool();
    let (mut state, _euid) = fresh_state(CardId::WellLaidPlans, 0, 0);
    // Bead `sts2-rs-4zxc0`: seed player HP before init so the
    // post-au4l2 `apply_power_to_creature` path (which gates on
    // `current_hp > 0`) accepts the player creature.
    state.player.current_hp = 70;
    state.player.max_hp = 70;
    let _ = state.init_player_creature();

    // Play WellLaidPlans (it's already on the play pile from
    // fresh_state). Applies the power.
    let f = lookup(CardId::WellLaidPlans).expect("registered");
    let r = f(&mut state, None);
    assert_eq!(r, EffectResult::Resolved);
    let wlp = state
        .powers
        .iter()
        .find(|p| p.kind == PowerKind::WellLaidPlans)
        .expect("WellLaidPlans power applied");
    assert_eq!(wlp.amount, 1, "1 stack applied (Python effect_vars)");

    // Move the played card off the play pile (it has been consumed)
    // and stage a fresh decoy card into the hand. The retain select
    // must offer exactly that decoy.
    state.player.play.clear();
    let decoy_uid_raw = NonZeroU32::new(2).expect("nz");
    state.cards.push(Card {
        uid: CardUid(decoy_uid_raw),
        card_id: CardId::StrikeSilent,
        cost: 1,
        card_type: CardType::Attack,
        target_type: TargetType::Enemy,
        upgraded: false,
        base_damage: 6,
        base_block: 0,
        ..Card::pod_defaults()
    });
    let decoy_uid = CardUid(decoy_uid_raw);
    state.player.hand.push(decoy_uid);

    // Run player end-turn phase one then phase two. Phase two must
    // SUSPEND on the WLP retain select (one eligible hand card).
    state.phase = CombatPhase::PlayerPlayPhase;
    end_player_turn_phase_one(&mut state);
    let r2 = end_player_turn_phase_two(&mut state);
    assert_eq!(
        r2,
        StepResult::PendingChoice,
        "phase two suspends on the WLP retain select"
    );
    let pc = state
        .pending_choice
        .as_ref()
        .expect("RetainAtTurnEnd choice surfaced");
    assert_eq!(pc.kind, ChoiceKind::RetainAtTurnEnd);
    assert_eq!(pc.min_select, 0, "min_select=0 — retain is optional");
    assert_eq!(pc.max_select, 1, "max_select=Amount (1 base)");
    assert!(pc.can_skip, "the player may retain nothing");
    assert_eq!(pc.options.len(), 1, "only the eligible decoy is offered");
    assert_eq!(pc.options[0].card_uid, Some(decoy_uid));
    assert!(
        state.pending_wlp_retain_resume,
        "flush parked behind the resume flag"
    );

    // Resolve: pick the decoy (option 0). The flush tail + the rest of
    // the end-turn chain resume.
    sts2_core::apply(
        &mut state,
        Action::ResolveChoice {
            selection: smallvec::smallvec![0u8],
        },
    );

    assert!(
        state.pending_choice.is_none(),
        "choice resolved — no lingering prompt"
    );
    assert!(
        !state.pending_wlp_retain_resume,
        "resume flag cleared after the flush tail ran"
    );
    assert!(
        state.player.hand.contains(&decoy_uid),
        "the chosen decoy was retained in hand through the flush"
    );
    assert!(
        !state.player.discard.contains(&decoy_uid),
        "the retained decoy must not be discarded"
    );
    assert_eq!(
        state.player.pending_retain_count, 0,
        "retain budget cleared after flush"
    );
    assert!(
        state.player.retain_this_turn.is_empty(),
        "retain_this_turn cleared after flush"
    );
}

/// Well-Laid Plans surfaces a `min=0/max=Amount` retain select; SKIPPING it
/// (selecting nothing) flushes the whole hand — the player retained nothing.
/// Mirrors C# `BeforeFlushLate` with an empty `FromHand` result. Bead
/// `sts2-rs-wlp-retain-select`.
#[test]
fn well_laid_plans_skip_retains_nothing() {
    use sts2_core::combat_loop::{end_player_turn_phase_one, end_player_turn_phase_two};
    use sts2_core::{Action, CardUid, ChoiceKind, CombatPhase, StepResult};
    install_pool();
    let (mut state, _euid) = fresh_state(CardId::WellLaidPlans, 0, 0);
    state.player.current_hp = 70;
    state.player.max_hp = 70;
    let _ = state.init_player_creature();
    let f = lookup(CardId::WellLaidPlans).expect("registered");
    assert_eq!(f(&mut state, None), EffectResult::Resolved);

    state.player.play.clear();
    let decoy_uid = CardUid(NonZeroU32::new(2).expect("nz"));
    state.cards.push(Card {
        uid: decoy_uid,
        card_id: CardId::StrikeSilent,
        cost: 1,
        card_type: CardType::Attack,
        target_type: TargetType::Enemy,
        ..Card::pod_defaults()
    });
    state.player.hand.push(decoy_uid);
    // Stack the draw pile with enough fillers that the resumed turn-start
    // draw pulls them (from the top) WITHOUT reshuffling the discard — so a
    // flushed decoy stays observably in discard rather than being re-drawn.
    for i in 0..8u32 {
        let fu = CardUid(NonZeroU32::new(100 + i).expect("nz"));
        state.cards.push(Card {
            uid: fu,
            card_id: CardId::StrikeSilent,
            cost: 1,
            card_type: CardType::Attack,
            target_type: TargetType::Enemy,
            ..Card::pod_defaults()
        });
        state.player.draw.push(fu);
    }

    state.phase = CombatPhase::PlayerPlayPhase;
    end_player_turn_phase_one(&mut state);
    let r2 = end_player_turn_phase_two(&mut state);
    assert_eq!(r2, StepResult::PendingChoice);
    assert_eq!(
        state.pending_choice.as_ref().map(|p| p.kind),
        Some(ChoiceKind::RetainAtTurnEnd)
    );

    // Resolve with an EMPTY selection (retain nothing).
    sts2_core::apply(
        &mut state,
        Action::ResolveChoice {
            selection: smallvec::SmallVec::new(),
        },
    );

    assert!(state.pending_choice.is_none());
    assert!(
        !state.player.hand.contains(&decoy_uid),
        "nothing retained — the decoy flushed out of hand"
    );
    assert!(
        state.player.discard.contains(&decoy_uid),
        "the un-retained decoy is in discard (not re-drawn — fillers fed the draw)"
    );
}

/// Well-Laid Plans with NO eligible card (the only hand card already
/// retains via the Retain keyword) opens NO prompt — phase two runs the
/// flush directly, mirroring C#'s empty `FromHand` early-return. Bead
/// `sts2-rs-wlp-retain-select`.
#[test]
fn well_laid_plans_no_eligible_card_no_prompt() {
    use sts2_core::combat_loop::{end_player_turn_phase_one, end_player_turn_phase_two};
    use sts2_core::{CardUid, CombatPhase, StepResult};
    install_pool();
    let (mut state, _euid) = fresh_state(CardId::WellLaidPlans, 0, 0);
    state.player.current_hp = 70;
    state.player.max_hp = 70;
    let _ = state.init_player_creature();
    let f = lookup(CardId::WellLaidPlans).expect("registered");
    assert_eq!(f(&mut state, None), EffectResult::Resolved);

    state.player.play.clear();
    // The lone hand card is already flagged to retain this turn, so the
    // RetainFilter (`!ShouldRetainThisTurn`) excludes it — zero options.
    let card_uid = CardUid(NonZeroU32::new(2).expect("nz"));
    state.cards.push(Card {
        uid: card_uid,
        card_id: CardId::StrikeSilent,
        cost: 1,
        card_type: CardType::Attack,
        target_type: TargetType::Enemy,
        ..Card::pod_defaults()
    });
    state.player.hand.push(card_uid);
    state.player.retain_this_turn.push(card_uid);

    state.phase = CombatPhase::PlayerPlayPhase;
    end_player_turn_phase_one(&mut state);
    let r2 = end_player_turn_phase_two(&mut state);
    assert_eq!(
        r2,
        StepResult::Advanced,
        "no eligible card — no prompt, flush runs inline"
    );
    assert!(state.pending_choice.is_none());
    assert!(!state.pending_wlp_retain_resume, "no suspend happened");
    // The pre-flagged card was kept in hand by the explicit retain set,
    // and the per-turn retain state is cleared after the flush.
    assert!(state.player.hand.contains(&card_uid));
    assert_eq!(state.player.pending_retain_count, 0);
    assert!(state.player.retain_this_turn.is_empty());
}

/// C# `CardSelectCmd.FromHand` returns empty once the combat
/// `IsOverOrEnding` (CardSelectCmd.cs:699), so a turn end whose last enemy is
/// already down opens no Well-Laid Plans retain select and does not park the
/// flush (Silent loadout v0.107.1 seed 1025: Rust suspended on a select that
/// `request_card_choice` refused to open).
#[test]
fn well_laid_plans_no_prompt_once_combat_is_ending() {
    use sts2_core::combat_loop::{end_player_turn_phase_one, end_player_turn_phase_two};
    use sts2_core::{CardUid, CombatPhase, StepResult};
    install_pool();
    let (mut state, euid) = fresh_state(CardId::WellLaidPlans, 0, 0);
    state.player.current_hp = 70;
    state.player.max_hp = 70;
    let _ = state.init_player_creature();
    let f = lookup(CardId::WellLaidPlans).expect("registered");
    assert_eq!(f(&mut state, None), EffectResult::Resolved);

    state.player.play.clear();
    let card_uid = CardUid(NonZeroU32::new(2).expect("nz"));
    state.cards.push(Card {
        uid: card_uid,
        card_id: CardId::StrikeSilent,
        cost: 1,
        card_type: CardType::Attack,
        target_type: TargetType::Enemy,
        ..Card::pod_defaults()
    });
    state.player.hand.push(card_uid);
    // The last enemy sits at 2 HP; the turn-end Lightning passive (3) downs
    // it after the end-turn win check, so combat is ending at the WLP step.
    if let Some(c) = state.creatures.iter_mut().find(|c| c.id == euid.0) {
        c.current_hp = 2;
    }
    state.player.orbs = sts2_core::orbs::OrbSlots::with_default_capacity();
    sts2_core::orbs::channel_orb(&mut state, sts2_core::orbs::Orb::lightning());

    state.phase = CombatPhase::PlayerPlayPhase;
    end_player_turn_phase_one(&mut state);
    let r2 = end_player_turn_phase_two(&mut state);
    assert_ne!(
        r2,
        StepResult::PendingChoice,
        "no retain select once ending"
    );
    assert_eq!(
        state
            .creatures
            .iter()
            .find(|c| c.id == euid.0)
            .map(|c| c.current_hp),
        Some(0),
        "the orb zap downed the enemy"
    );
    assert!(state.pending_choice.is_none());
    assert!(!state.pending_wlp_retain_resume, "flush not parked");
    assert_eq!(state.player.pending_retain_count, 0);
}

