// ---- Bead `sts2-rs-q6bix`: Sly does NOT trigger on end-of-turn flush ----
/// Reflex (Sly) does **not** draw when flushed from hand at end of
/// turn. C# routes the end-of-turn hand flush through
/// `CardPileCmd.Add(list2, discardPile)`
/// (`CombatManager.EndPlayerTurnPhaseTwoInternal`), which fires
/// **neither** `Hook.AfterCardDiscarded` **nor** the Sly auto-play
/// loop — those live only on the active `CardCmd.DiscardAndDraw`
/// path (`CardCmd.cs:144-159`). So a Sly card left in hand at end of
/// turn just moves to discard with no side effect.
///
/// The prior `reflex_on_discard_draws_two` test (bead `sts2-rs-ymlf`)
/// encoded the Python pin's behavior of firing `after_card_discarded`
/// on the flush — a fabrication vs C#. q6bix coverage-sweep root fix
/// removed that flush dispatch; Reflex's draw now fires only on an
/// active discard (which still routes through
/// `dispatch_after_card_discarded`).
#[test]
fn reflex_does_not_draw_on_end_of_turn_flush() {
    use sts2_core::combat_loop::{end_player_turn_phase_one, end_player_turn_phase_two};
    use sts2_core::{CardUid, CombatPhase};
    install_pool();
    // Start with Reflex in hand. fresh_state pushes the card to
    // play; reset that and stage Reflex in hand instead.
    let (mut state, _euid) = fresh_state(CardId::Reflex, 0, 0);
    // Live player — see explicit_retain_flag_survives_flush.
    state.player.current_hp = 70;
    state.player.max_hp = 70;
    let _ = state.init_player_creature();
    state.player.play.clear();
    let reflex_uid = CardUid(NonZeroU32::new(1).expect("nz"));
    state.player.hand.push(reflex_uid);

    // Stack 3 sentinel cards in the draw pile so the listener can
    // pull 2 of them into hand at flush time. Use a non-Reflex id
    // so we can distinguish the drawn cards from Reflex itself.
    let mut draw_uids: Vec<CardUid> = Vec::new();
    for slot in 2_u32..=4 {
        let raw = NonZeroU32::new(slot).expect("nz");
        state.cards.push(Card {
            uid: CardUid(raw),
            card_id: CardId::StrikeSilent,
            cost: 1,
            card_type: CardType::Attack,
            target_type: TargetType::Enemy,
            upgraded: false,
            base_damage: 6,
            base_block: 0,
            ..Card::pod_defaults()
        });
        let uid = CardUid(raw);
        draw_uids.push(uid);
        state.player.draw.push(uid);
    }

    // Run end-turn flush. Reflex moves hand -> discard via the
    // flush; C# fires no discard hook here, so Reflex draws nothing.
    state.phase = CombatPhase::PlayerPlayPhase;
    end_player_turn_phase_one(&mut state);
    end_player_turn_phase_two(&mut state);

    // Reflex itself is in discard.
    assert!(
        state.player.discard.contains(&reflex_uid),
        "Reflex moves to discard via the flush"
    );
    // No sentinel draw-pile cards were pulled — the flush is not a
    // Sly/discard-hook trigger.
    let drawn_in_hand = draw_uids
        .iter()
        .filter(|u| state.player.hand.contains(u))
        .count();
    assert_eq!(
        drawn_in_hand, 0,
        "Sly does not auto-play on the end-of-turn flush (C# CardPileCmd.Add)"
    );
    // All three remain in the draw pile.
    let still_in_draw = draw_uids
        .iter()
        .filter(|u| state.player.draw.contains(u))
        .count();
    assert_eq!(still_in_draw, 3, "the flush draws nothing");
}

// ---- Bead `sts2-rs-q6bix`: Tingsha does NOT fire on flush ----
/// Tingsha deals no damage when the hand is flushed at end of turn.
/// Same root as the Reflex case: C#'s end-of-turn flush uses
/// `CardPileCmd.Add` and never invokes `Hook.AfterCardDiscarded`, so
/// Tingsha (an `AfterCardDiscarded` listener) is silent on the flush.
/// It still fires on an active player-turn discard (covered by the
/// core `tingsha_damages_random_enemy_on_player_side_discard` test).
///
/// q6bix coverage sweep (seed 249, relic=TINGSHA): on a bare
/// `end_turn`, C# left both enemies at full HP while Rust dealt 3 to
/// each from the flush — the divergence this fix closes.
#[test]
fn tingsha_does_not_fire_on_end_of_turn_flush() {
    use sts2_core::combat_loop::{end_player_turn_phase_one, end_player_turn_phase_two};
    use sts2_core::{CardUid, CombatPhase};
    install_pool();
    sts2_core::relic_effects::ensure_installed();
    // Enemy at uid=1, a card staged in hand to be flushed.
    let (mut state, euid) = fresh_state(CardId::StrikeSilent, 6, 0);
    let _ = state.init_player_creature();
    state.player.play.clear();
    let hand_uid = CardUid(NonZeroU32::new(1).expect("nz"));
    state.player.hand.push(hand_uid);
    // Player owns Tingsha.
    state.relics.push(sts2_core::Relic {
        id: NonZeroU32::new(100).expect("nz"),
        kind: sts2_core::RelicKind::Tingsha,
        counter: 0,
        is_wax: false,
        is_melted: false,
    });
    let enemy_hp = |s: &sts2_core::CombatState| {
        s.creatures
            .iter()
            .find(|c| c.id == euid.0)
            .map(|c| c.current_hp)
            .expect("enemy present")
    };
    let hp_before = enemy_hp(&state);

    state.phase = CombatPhase::PlayerPlayPhase;
    end_player_turn_phase_one(&mut state);
    end_player_turn_phase_two(&mut state);

    assert_eq!(
        enemy_hp(&state),
        hp_before,
        "Tingsha must not damage enemies on the end-of-turn flush (C# fires no discard hook there)"
    );
}

