// ---- G3 random-target routing (bead `sts2-rs-xuk`) -----------------
//
// Mirrors the Python pin's per-hit `combat.rng.choice(alive)` shape on
// a 3-enemy combat with the 3-hit Ricochet card. Verifies:
//  1. dispatch is reachable for `TargetType::Random` (no short-circuit
//     in `combat_loop::play_card`);
//  2. the handler calls `state.get_random_enemy()` once per hit (3
//     RNG draws → 3 damage applications);
//  3. RNG determinism: the same Rust seed produces the same per-hit
//     pick sequence — locked here as a regression anchor. (Byte-equal
//     parity with Python is not achievable because the Rust RNG is
//     Xoshiro256PlusPlus while Python uses Mersenne Twister; per
//     `tests/parity/known_divergences.md` schema, RNG-byte parity is
//     out of scope. The call-shape — 3 picks from
//     `alive_enemies` — is the parity contract.)
/// Build a 3-enemy combat with Ricochet in hand and the dispatch
/// registry installed. Returns (state, ricochet card_uid).
fn three_enemy_ricochet_state(seed: u64) -> CombatState {
    install_pool();
    let mut state = CombatState {
        rng: sts2_core::dotnet_rng::Rng::new((seed) as i32),
        ..Default::default()
    };
    // 3 enemies with 50 HP each so a 3-dmg hit doesn't kill anyone.
    for slot in 1_u32..=3 {
        let id = NonZeroU32::new(slot).expect("nz");
        state.creatures.push(Creature {
            id,
            current_hp: 50,
            max_hp: 50,
            block: 0,
            powers: SmallVec::new(),
            species: Some(MonsterKind::Nibbit),
            intent: None,
            intent_history: IntentHistory::default(),
            monster_id: MonsterId("Nibbit"),
            ai: None,
        });
        state.enemy_uids.push(CreatureUid(id));
    }
    // Player Creature is required by the damage pipeline.
    state.player.current_hp = 80;
    state.player.max_hp = 80;
    let _ = state.init_player_creature();

    // Push the Ricochet card POD (uid is 1-based against state.cards).
    let card_uid_raw = NonZeroU32::new(1).expect("nz");
    state.cards.push(Card {
        uid: sts2_core::CardUid(card_uid_raw),
        card_id: CardId::Ricochet,
        cost: 2,
        card_type: CardType::Attack,
        target_type: TargetType::Random,
        upgraded: false,
        base_damage: 3,
        base_block: 0,
        ..Card::pod_defaults()
    });
    // Card on top of Play pile so `originating_card_id` resolves.
    state.player.play.push(sts2_core::CardUid(card_uid_raw));
    state
}

#[test]
fn random_target_routing_four_hit_ricochet() {
    // Bead `sts2-rs-chjks`: C# Ricochet RepeatVar(4) → 4 hits (not 3).
    let mut state = three_enemy_ricochet_state(42);

    let f = lookup(CardId::Ricochet).expect("registered");
    let r = f(&mut state, None); // combat_loop passes None for Random.
    assert_eq!(r, EffectResult::Resolved);

    // 12 = 3 dmg × 4 hits total — every hit landed on *some* alive enemy.
    let total_dmg: i32 = state
        .creatures
        .iter()
        .filter(|c| c.id.get() <= 3) // exclude the player Creature
        .map(|c| c.max_hp - c.current_hp)
        .sum();
    assert_eq!(
        total_dmg, 12,
        "Ricochet 4-hit fan-out should sum to 12 dmg across the 3-enemy board",
    );
}

#[test]
fn ricochet_upgraded_hits_five_times() {
    // Bead `sts2-rs-chjks`: C# Ricochet OnUpgrade bumps RepeatVar 4 → 5.
    let mut state = three_enemy_ricochet_state(42);
    state.cards[0].upgraded = true;

    let f = lookup(CardId::Ricochet).expect("registered");
    assert_eq!(f(&mut state, None), EffectResult::Resolved);

    // 15 = 3 dmg × 5 hits (enemies have 50 HP, none die).
    let total_dmg: i32 = state
        .creatures
        .iter()
        .filter(|c| c.id.get() <= 3)
        .map(|c| c.max_hp - c.current_hp)
        .sum();
    assert_eq!(total_dmg, 15, "Ricochet+ should fan out 5 hits → 15 dmg");
}

#[test]
fn random_target_routing_is_rng_deterministic() {
    // Same seed → same per-hit pick sequence → same per-enemy HP loss.
    let mut a = three_enemy_ricochet_state(7);
    let mut b = three_enemy_ricochet_state(7);
    let f = lookup(CardId::Ricochet).expect("registered");
    f(&mut a, None);
    f(&mut b, None);
    for slot in 1_u32..=3 {
        let id = NonZeroU32::new(slot).expect("nz");
        let hp_a = a
            .creatures
            .iter()
            .find(|c| c.id == id)
            .expect("enemy present")
            .current_hp;
        let hp_b = b
            .creatures
            .iter()
            .find(|c| c.id == id)
            .expect("enemy present")
            .current_hp;
        assert_eq!(hp_a, hp_b, "RNG-determinism violated for enemy {slot}");
    }
}

#[test]
fn random_target_routing_breaks_when_board_clears() {
    // 1 enemy at low HP → first hit kills it → subsequent hits should
    // see `get_random_enemy() == None` and break out of the loop.

    install_pool();
    let mut state = CombatState {
        rng: sts2_core::dotnet_rng::Rng::new(0_i32),
        ..Default::default()
    };
    let id = NonZeroU32::new(1).expect("nz");
    state.creatures.push(Creature {
        id,
        current_hp: 2, // 3-dmg hit overkills.
        max_hp: 2,
        block: 0,
        powers: SmallVec::new(),
        species: Some(MonsterKind::Nibbit),
        intent: None,
        intent_history: IntentHistory::default(),
        monster_id: MonsterId("Nibbit"),
        ai: None,
    });
    state.enemy_uids.push(CreatureUid(id));
    state.player.current_hp = 80;
    state.player.max_hp = 80;
    let _ = state.init_player_creature();
    let card_uid_raw = NonZeroU32::new(1).expect("nz");
    state.cards.push(Card {
        uid: sts2_core::CardUid(card_uid_raw),
        card_id: CardId::Ricochet,
        cost: 2,
        card_type: CardType::Attack,
        target_type: TargetType::Random,
        upgraded: false,
        base_damage: 3,
        base_block: 0,
        ..Card::pod_defaults()
    });
    state.player.play.push(sts2_core::CardUid(card_uid_raw));

    let f = lookup(CardId::Ricochet).expect("registered");
    f(&mut state, None);
    // Lone enemy dead after the first hit; remaining 2 hits should
    // see `get_random_enemy() == None` and the loop breaks cleanly.
    let enemy = state
        .creatures
        .iter()
        .find(|c| c.id == id)
        .expect("enemy present");
    assert_eq!(enemy.current_hp, 0, "first hit kills the lone enemy");
}

