/// `SpeedsterPower.AfterCardDrawn` (C# `SpeedsterPower.cs:18-27`): a card
/// drawn by a CARD EFFECT (`fromHandDraw == false`) deals `Amount` Unpowered
/// damage to every enemy, once per drawn card; the turn-start hand draw
/// (`fromHandDraw == true`) does NOT trigger it. Regression for the prior
/// mis-port that modeled Speedster as a (no-op) cost reduction.
#[test]
fn speedster_damages_enemies_on_card_effect_draw_not_hand_draw() {
    install_pool();
    let (mut state, _euid) = fresh_state(CardId::SpeedsterCard, 0, 0);
    // Second enemy so we can assert "all enemies" coverage.
    let e2 = NonZeroU32::new(2).expect("nz");
    state.creatures.push(Creature {
        id: e2,
        current_hp: 100,
        max_hp: 100,
        block: 0,
        powers: SmallVec::new(),
        species: Some(MonsterKind::Nibbit),
        intent: None,
        intent_history: IntentHistory::default(),
        monster_id: MonsterId("Nibbit"),
        ai: None,
    });
    state.enemy_uids.push(CreatureUid(e2));
    // Speedster(2) on the player.
    apply_power_to_player(&mut state, PowerKind::Speedster, 2);
    // Three drawable cards in the draw pile.
    for _ in 0..3_u32 {
        let raw = u32::try_from(state.cards.len() + 1).expect("fits");
        let uid = sts2_core::CardUid::new(raw).expect("non-zero");
        state.cards.push(Card {
            uid,
            card_id: CardId::DefendSilent,
            cost: 1,
            card_type: CardType::Skill,
            target_type: TargetType::Self_,
            upgraded: false,
            base_damage: 0,
            base_block: 5,
            ..Card::pod_defaults()
        });
        state.player.draw.push(uid);
    }
    // Card-effect draw of 1 card → 2 damage to BOTH enemies.
    let _ = sts2_core::cards::draw_via_state(&mut state, 1);
    assert_eq!(
        state.creatures[0].current_hp, 98,
        "enemy0 took 2 from Speedster"
    );
    assert_eq!(
        state.creatures[1].current_hp, 98,
        "enemy1 took 2 from Speedster"
    );
    // Turn-start hand draw of the remaining card → NO Speedster damage.
    let _ = state.draw_into_hand(1);
    assert_eq!(
        state.creatures[0].current_hp, 98,
        "hand-draw does not trigger Speedster"
    );
    assert_eq!(
        state.creatures[1].current_hp, 98,
        "hand-draw does not trigger Speedster"
    );
    // A card-effect draw during the ENEMY turn (Centennial Puzzle on an enemy
    // hit) fails the `CurrentSide == Owner.Side` gate (`SpeedsterPower.cs:17`).
    state.side = sts2_core::Side::Enemy;
    let _ = sts2_core::cards::draw_via_state(&mut state, 1);
    assert_eq!(
        state.creatures[0].current_hp, 98,
        "enemy-turn draw does not trigger Speedster"
    );
    assert_eq!(
        state.creatures[1].current_hp, 98,
        "enemy-turn draw does not trigger Speedster"
    );
}

