/// `PhantomBladesPower.ModifyDamageAdditive` (C# `PhantomBladesPower.cs:53-72`):
/// only the FIRST Shiv played each turn deals `+Amount`; subsequent Shivs
/// (counter already bumped) get no bonus. Regression for the deferred arm.
#[test]
fn phantom_blades_boosts_only_first_shiv_of_turn() {
    install_pool();
    let (mut state, euid) = fresh_state(CardId::Shiv, 4, 0);
    state.cards[0].tags = sts2_core::cards::CardTags::one(sts2_core::cards::CardTag::Shiv);
    apply_power_to_player(&mut state, PowerKind::PhantomBlades, 9);
    // First Shiv of the turn (shivs_played_this_turn == 0): 4 + 9 = 13.
    let before = state.creatures[0].current_hp;
    let _ = sts2_core::card_effects::deal_damage_player_to_enemy(&mut state, euid, 4);
    assert_eq!(
        before - state.creatures[0].current_hp,
        13,
        "first Shiv 4 + 9"
    );
    // After a Shiv has finished playing this turn, the bonus is spent.
    state.player.shivs_played_this_turn = 1;
    let before2 = state.creatures[0].current_hp;
    let _ = sts2_core::card_effects::deal_damage_player_to_enemy(&mut state, euid, 4);
    assert_eq!(
        before2 - state.creatures[0].current_hp,
        4,
        "second Shiv gets no PhantomBlades bonus"
    );
}

