/// A SECOND Tracking play applies only +1 (C# `Tracking.OnPlay`:
/// `if HasPower<TrackingPower>() Apply(1) else Apply(2)`), so the total is 3 —
/// NOT 4. The bug (`sts2-rs-trackmerge`) was that the `HasPower` check walked
/// only the legacy `state.player.powers` list while `apply_power_to_player`
/// routes the stack onto the d03 mirror creature, so the second play never
/// saw the first instance and re-applied the full +2. This test wires the
/// player→Creature mirror so the legacy-only check would regress to 4.
#[test]
fn play_tracking_twice_with_mirror_totals_3_not_4() {
    install_pool();
    let (mut state, _) = fresh_state(CardId::Tracking, 0, 0);
    // Wire the player → Creature mirror — `apply_power_to_player` then routes
    // the Tracking stack onto `state.creatures[player]`, not the legacy list.
    let player_id = NonZeroU32::new(99).expect("non-zero");
    state.creatures.push(Creature {
        id: player_id,
        current_hp: 80,
        max_hp: 80,
        block: 0,
        powers: SmallVec::new(),
        species: None,
        intent: None,
        intent_history: IntentHistory::default(),
        monster_id: MonsterId("Player"),
        ai: None,
    });
    state.player.creature_uid = Some(CreatureUid(player_id));

    let f = lookup(CardId::Tracking).expect("registered");
    let _ = f(&mut state, None);
    let _ = f(&mut state, None);
    let total: i32 = state
        .powers
        .iter()
        .filter(|p| p.kind == PowerKind::Tracking)
        .map(|p| p.amount)
        .sum();
    assert_eq!(total, 3, "two Tracking plays must total 3 (2 + 1), not 4");
}

