/// PreciseCut: the calculated base (13 - 2*hand_count) can go NEGATIVE; the
/// clamp to >=0 must happen AFTER Strength is added (C# `Hook.ModifyDamage`),
/// not before. With a large hand the base underflows, and Strength must not
/// resurrect the floored-0 hit into positive damage. Regression for Silent fuzz
/// seed 238 (hand 8 -> base -1, +Strength 1: C# deals 0, Rust previously 1).
#[test]
fn play_precise_cut_negative_base_clamps_after_strength() {
    use sts2_core::{Power, PowerUid};
    install_pool();
    let (mut state, euid) = fresh_state(CardId::PreciseCut, 13, 0);
    // 8 cards in hand -> base = 13 - 2*8 = -3.
    for i in 0..8 {
        state
            .player
            .hand
            .push(sts2_core::CardUid(NonZeroU32::new(100 + i).expect("nz")));
    }
    // Player Strength(1): must NOT lift the floored-0 hit to 1.
    let pid = NonZeroU32::new(900).expect("nz");
    state.powers.push(Power {
        id: pid,
        kind: PowerKind::Strength,
        amount: 1,
        counter: 0,
        applier: None,
        skip_next_tick: false,
    });
    state.player.powers.push(PowerUid(pid));
    let _ = lookup(CardId::PreciseCut).expect("registered")(&mut state, Some(euid));
    assert_eq!(
        state.creatures[0].current_hp, 100,
        "base -3 + Strength 1 = -2 -> clamp 0: no damage (clamp is post-Strength)"
    );
}

/// GrandFinale's AoE must LOCK every target's damage against the
/// pre-death dealer state before any kill resolves — C# `DamageCmd
/// .Attack(60).TargetingAllOpponents` routes through `CreatureCmd.Damage`,
/// which computes `Hook.ModifyDamage` for EVERY target up-front
/// (`CreatureCmd.cs:134-151`) and calls `Kill` only once after the whole
/// loop (`CreatureCmd.cs:285`). The player carries an infinite Shrink(-1)
/// applied by a ShrinkerBeetle (powered attacks deal ×0.70). GrandFinale
/// (base 60, ValueProp.Move = powered) fans over [beetle@21, wurm@57]:
/// both hits lock at 60×0.70=42. The beetle dies to its 42 and its Shrink
/// `AfterDeath` strips the player's Shrink — but the wurm's hit was already
/// locked at 42, so the wurm ends at 57-42=15 HP, ALIVE.
///
/// The pre-fix Silent helper looped `deal_damage_player_to_enemy` per
/// enemy, fully resolving each enemy's death (incl. Shrink removal) BEFORE
/// computing the next enemy's damage — so the wurm was recomputed at the
/// full un-shrunk 60 after the beetle's death and died, wrongly clearing
/// the board (issue #175, seed 2080, bucket MONSTER_STATE|GRAND_FINALE).
#[test]
fn grand_finale_aoe_locks_damage_before_mid_aoe_shrink_removal() {
    install_pool();
    let mut state = CombatState {
        rng: sts2_core::dotnet_rng::Rng::new(0_i32),
        ..Default::default()
    };
    // Enemy 0 = ShrinkerBeetle @ 21 HP — the applier of the player's Shrink.
    let beetle_id = NonZeroU32::new(1).expect("nz");
    state.creatures.push(Creature {
        id: beetle_id,
        current_hp: 21,
        max_hp: 21,
        block: 0,
        powers: SmallVec::new(),
        species: Some(MonsterKind::ShrinkerBeetle),
        intent: None,
        intent_history: IntentHistory::default(),
        monster_id: MonsterId("ShrinkerBeetle"),
        ai: None,
    });
    let beetle = CreatureUid(beetle_id);
    state.enemy_uids.push(beetle);
    // Enemy 1 = FuzzyWurmCrawler @ 57 HP — survives the locked 42 with 15 HP.
    let wurm_id = NonZeroU32::new(2).expect("nz");
    state.creatures.push(Creature {
        id: wurm_id,
        current_hp: 57,
        max_hp: 57,
        block: 0,
        powers: SmallVec::new(),
        species: Some(MonsterKind::FuzzyWurmCrawler),
        intent: None,
        intent_history: IntentHistory::default(),
        monster_id: MonsterId("FuzzyWurmCrawler"),
        ai: None,
    });
    state.enemy_uids.push(CreatureUid(wurm_id));
    // Player carries an infinite Shrink(-1) APPLIED BY the beetle (so the
    // beetle's death strips it via `remove_shrink_from_dead_applier`).
    let shrink_id = NonZeroU32::new(900).expect("nz");
    state.powers.push(Power {
        id: shrink_id,
        kind: PowerKind::Shrink,
        amount: -1,
        counter: 0,
        applier: Some(beetle),
        skip_next_tick: false,
    });
    state.player.powers.push(PowerUid(shrink_id));
    // The GrandFinale being resolved, on the Play pile (draw pile is empty,
    // so its `IsPlayable` body fires). Base 60.
    state.cards.push(Card {
        uid: sts2_core::CardUid(NonZeroU32::new(1).expect("nz")),
        card_id: CardId::GrandFinale,
        cost: 0,
        card_type: CardType::Attack,
        target_type: TargetType::AllEnemies,
        base_damage: 60,
        ..Card::pod_defaults()
    });
    state
        .player
        .play
        .push(sts2_core::CardUid(NonZeroU32::new(1).expect("nz")));

    let _ = lookup(CardId::GrandFinale).expect("registered")(&mut state, None);

    // Beetle dies to its locked 42 (>= 21).
    let beetle_hp = state
        .creatures
        .iter()
        .find(|c| c.id == beetle_id)
        .map_or(0, |c| c.current_hp);
    assert!(beetle_hp <= 0, "ShrinkerBeetle (21 HP) dies to 60×0.70=42");
    // Wurm's hit was LOCKED at 42 before the beetle's death removed Shrink,
    // so it survives at 57-42=15 — NOT recomputed at the un-shrunk 60.
    let wurm_hp = state
        .creatures
        .iter()
        .find(|c| c.id == wurm_id)
        .map_or(0, |c| c.current_hp);
    assert_eq!(
        wurm_hp, 15,
        "wurm damage must lock at 42 (Shrink present) before the beetle's \
         death strips Shrink — the per-enemy interleave wrongly dealt 60 → dead"
    );
}

/// Grand Finale's `OnPlay` deals damage UNCONDITIONALLY — the draw-empty rule
/// is `IsPlayable` (manual-play legality only), which `CardCmd.AutoPlay` skips.
/// So an auto-played Grand Finale (Catastrophe / Mayhem / HistoryCourse) with a
/// NON-empty draw pile must still deal its damage. The old `OnPlay` draw-empty
/// guard wrongly no-op'd it (catastrophe-autoplay bug 3, potion fix 2).
#[test]
fn grand_finale_deals_damage_with_nonempty_draw_pile() {
    install_pool();
    let mut state = CombatState {
        rng: sts2_core::dotnet_rng::Rng::new(0_i32),
        ..Default::default()
    };
    let enemy_id = NonZeroU32::new(1).expect("nz");
    state.creatures.push(Creature {
        id: enemy_id,
        current_hp: 100,
        max_hp: 100,
        block: 0,
        powers: SmallVec::new(),
        species: Some(MonsterKind::FuzzyWurmCrawler),
        intent: None,
        intent_history: IntentHistory::default(),
        monster_id: MonsterId("FuzzyWurmCrawler"),
        ai: None,
    });
    state.enemy_uids.push(CreatureUid(enemy_id));
    // GrandFinale being resolved, on the Play pile. Base 60.
    state.cards.push(Card {
        uid: sts2_core::CardUid(NonZeroU32::new(1).expect("nz")),
        card_id: CardId::GrandFinale,
        cost: 0,
        card_type: CardType::Attack,
        target_type: TargetType::AllEnemies,
        base_damage: 60,
        ..Card::pod_defaults()
    });
    state
        .player
        .play
        .push(sts2_core::CardUid(NonZeroU32::new(1).expect("nz")));
    // A card sits in the DRAW pile → `IsPlayable` would be false, but auto-play
    // ignores it. Any non-zero draw-pile card reproduces the auto-play case.
    state.cards.push(Card {
        uid: sts2_core::CardUid(NonZeroU32::new(2).expect("nz")),
        card_id: CardId::StrikeSilent,
        cost: 1,
        card_type: CardType::Attack,
        target_type: TargetType::Enemy,
        base_damage: 6,
        ..Card::pod_defaults()
    });
    state
        .player
        .draw
        .push(sts2_core::CardUid(NonZeroU32::new(2).expect("nz")));

    let _ = lookup(CardId::GrandFinale).expect("registered")(&mut state, None);

    let enemy_hp = state
        .creatures
        .iter()
        .find(|c| c.id == enemy_id)
        .map_or(0, |c| c.current_hp);
    assert_eq!(
        enemy_hp, 40,
        "Grand Finale deals 60 even with a non-empty draw pile (auto-play case)"
    );
}

/// KnifeTrap auto-plays each exhaust-pile Shiv as a REAL card play (C#
/// `KnifeTrap.cs` `CardCmd.AutoPlay(item, cardPlay.Target)`), not a raw damage
/// tick. The prior port short-circuited to `deal_damage_player_to_enemy`, which
/// skipped the surrounding `OnPlayWrapper` machinery — so no card-play counter
/// advanced and no `Before/AfterCardPlayed` power fired (Silent sweep
/// `PLAYER_STATE|KNIFE_TRAP` / `MONSTER_STATE|KNIFE_TRAP` seeds 315/551). Assert
/// both the damage AND that the combat-wide play counter ticked once per Shiv.
#[test]
fn knife_trap_auto_plays_each_exhaust_shiv_as_real_card_play() {
    install_pool();
    super::super::status::install_pool(); // registers Shiv's dispatch + EXHAUST
    let mut state = CombatState {
        rng: sts2_core::dotnet_rng::Rng::new(0_i32),
        ..Default::default()
    };
    // Alive player: a dead one ends the combat, and C# `CardCmd.AutoPlay`
    // does nothing once combat `IsOverOrEnding` (CardCmd.cs:54).
    state.player.current_hp = 80;
    state.player.max_hp = 80;
    let enemy_id = NonZeroU32::new(1).expect("nz");
    state.creatures.push(Creature {
        id: enemy_id,
        current_hp: 100,
        max_hp: 100,
        block: 0,
        powers: SmallVec::new(),
        species: Some(MonsterKind::Nibbit),
        intent: None,
        intent_history: IntentHistory::default(),
        monster_id: MonsterId("Nibbit"),
        ai: None,
    });
    let euid = CreatureUid(enemy_id);
    state.enemy_uids.push(euid);
    // Card uid 1 = the KnifeTrap being resolved, on the Play pile.
    state.cards.push(Card {
        uid: sts2_core::CardUid(NonZeroU32::new(1).expect("nz")),
        card_id: CardId::KnifeTrap,
        cost: 2,
        card_type: CardType::Skill,
        target_type: TargetType::Enemy,
        ..Card::pod_defaults()
    });
    state
        .player
        .play
        .push(sts2_core::CardUid(NonZeroU32::new(1).expect("nz")));
    // Two Shivs (4 damage each) sitting in the exhaust pile.
    for i in 2..=3u32 {
        let uid = sts2_core::CardUid(NonZeroU32::new(i).expect("nz"));
        state.cards.push(Card {
            uid,
            card_id: CardId::Shiv,
            cost: 0,
            card_type: CardType::Attack,
            target_type: TargetType::Enemy,
            base_damage: 4,
            ..Card::pod_defaults()
        });
        state.player.exhaust.push(uid);
    }
    let _ = lookup(CardId::KnifeTrap).expect("registered")(&mut state, Some(euid));
    assert_eq!(
        state.creatures[0].current_hp,
        100 - 8,
        "two exhaust-pile Shivs deal 4 damage each"
    );
    assert_eq!(
        state.combat_log.player_card_plays_this_combat, 2,
        "each auto-played Shiv is a real card play (the raw-damage port left this 0)"
    );
    // (Exhaust-tail re-ordering — the `EXHAUST_FATE|KNIFE_TRAP` residual — is
    // covered by the C# parity sweep; the POD Shivs here aren't wired into the
    // CardId EXHAUST registry, so their natural result pile is Discard.)
}

/// CalculatedGamble (= C# `CardCmd.DiscardAndDraw(hand, hand.Count)`) auto-plays
/// every discarded `IsSlyThisTurn` card — which is `Sly` keyword OR a
/// single-turn Sly applied by HandTrick (`player.sly_this_turn`). The prior
/// inline port filtered on the permanent keyword only, so a HandTrick-marked
/// DEADLY_POISON discarded by CalculatedGamble was NOT auto-played and applied
/// no Poison (Silent sweep `DRAW_ORDER|CALCULATED_GAMBLE` seed 176). Assert the
/// single-turn-Sly card auto-plays and applies its Poison.
#[test]
fn calculated_gamble_auto_plays_single_turn_sly_discard() {
    install_pool();
    let mut state = CombatState {
        rng: sts2_core::dotnet_rng::Rng::new(0_i32),
        ..Default::default()
    };
    // Alive player: a dead one ends the combat, and C# `CardCmd.AutoPlay`
    // does nothing once combat `IsOverOrEnding` (CardCmd.cs:54).
    state.player.current_hp = 80;
    state.player.max_hp = 80;
    let enemy_id = NonZeroU32::new(1).expect("nz");
    state.creatures.push(Creature {
        id: enemy_id,
        current_hp: 100,
        max_hp: 100,
        block: 0,
        powers: SmallVec::new(),
        species: Some(MonsterKind::Nibbit),
        intent: None,
        intent_history: IntentHistory::default(),
        monster_id: MonsterId("Nibbit"),
        ai: None,
    });
    let euid = CreatureUid(enemy_id);
    state.enemy_uids.push(euid);
    // uid 1 = CalculatedGamble being resolved (on Play).
    state.cards.push(Card {
        uid: sts2_core::CardUid(NonZeroU32::new(1).expect("nz")),
        card_id: CardId::CalculatedGamble,
        cost: 0,
        card_type: CardType::Skill,
        target_type: TargetType::Self_,
        ..Card::pod_defaults()
    });
    state
        .player
        .play
        .push(sts2_core::CardUid(NonZeroU32::new(1).expect("nz")));
    // uid 2 = DEADLY_POISON in hand, made Sly for this turn (à la HandTrick).
    let dp = sts2_core::CardUid(NonZeroU32::new(2).expect("nz"));
    state.cards.push(Card {
        uid: dp,
        card_id: CardId::DeadlyPoison,
        cost: 1,
        card_type: CardType::Skill,
        target_type: TargetType::Enemy,
        ..Card::pod_defaults()
    });
    state.player.hand.push(dp);
    state.player.sly_this_turn.push(dp);
    // uid 3 = a filler card in the draw pile so the count-sized draw has a card
    // to take (avoids a discard->draw reshuffle relocating DEADLY_POISON).
    let filler = sts2_core::CardUid(NonZeroU32::new(3).expect("nz"));
    state.cards.push(Card {
        uid: filler,
        card_id: CardId::DefendSilent,
        cost: 1,
        card_type: CardType::Skill,
        target_type: TargetType::Self_,
        base_block: 5,
        ..Card::pod_defaults()
    });
    state.player.draw.push(filler);
    let _ = lookup(CardId::CalculatedGamble).expect("registered")(&mut state, None);
    let enemy_poison = state.creatures[0].powers.iter().find_map(|pu| {
        state
            .powers
            .iter()
            .find(|p| p.id == pu.0 && p.kind == PowerKind::Poison)
            .map(|p| p.amount)
    });
    assert_eq!(
        enemy_poison,
        Some(5),
        "single-turn-Sly DEADLY_POISON is auto-played from the discard and applies 5 Poison"
    );
}

/// Regression: a REFLEX discarded through an active-discard surface
/// (`discard_and_draw_with_hooks`, which fires `AfterCardDiscarded`) draws
/// EXACTLY 2 — its `OnPlay` via the Sly auto-play — not 4. REFLEX used to draw
/// from TWO sources on the same discard: the Sly auto-play (`OnPlay`) AND a
/// redundant card-id-keyed arm in `dispatch_after_card_discarded`. Routing
/// CalculatedGamble's discard through the hook-firing helper surfaced the
/// double-draw and shifted the reshuffle point vs C# (Silent sweep
/// `HAND_COST|CALCULATED_GAMBLE` seed 849). With the listener removed REFLEX has
/// a single draw source. Here: discard REFLEX, draw 1 (= hand.Count), then the
/// Sly auto-play draws 2 → 3 sentinels enter hand (a 5 would mean a double
/// source).
#[test]
fn reflex_discarded_via_helper_draws_two_not_four() {
    install_pool();
    // `install_pool` registers play fns only; the SLY registry is filled by the
    // full content install's `install_sly_keywords`. Register REFLEX's keyword
    // directly so `card_sly(Reflex)` is true (idiom from `tactician_*` test).
    sts2_core::card_effects::register_card_sly(CardId::Reflex);
    let mut state = CombatState {
        rng: sts2_core::dotnet_rng::Rng::new(0_i32),
        ..Default::default()
    };
    // A live player: a dead one makes the combat ending, so draws move no card.
    state.player.current_hp = 80;
    // REFLEX (uid 1) in hand — `Sly` keyword (registered above).
    let reflex = sts2_core::CardUid(NonZeroU32::new(1).expect("nz"));
    state.cards.push(Card {
        uid: reflex,
        card_id: CardId::Reflex,
        cost: 3,
        card_type: CardType::Skill,
        target_type: TargetType::Self_,
        ..Card::pod_defaults()
    });
    state.player.hand.push(reflex);
    // 6 sentinels in the draw pile so neither the count-draw nor REFLEX's draw
    // reshuffles. Distinct ids so we can count exactly what entered hand.
    let mut sentinels = Vec::new();
    for slot in 2_u32..=7 {
        let uid = sts2_core::CardUid(NonZeroU32::new(slot).expect("nz"));
        state.cards.push(Card {
            uid,
            card_id: CardId::DefendSilent,
            cost: 1,
            card_type: CardType::Skill,
            target_type: TargetType::Self_,
            base_block: 5,
            ..Card::pod_defaults()
        });
        sentinels.push(uid);
        state.player.draw.push(uid);
    }
    // C# `DiscardAndDraw([REFLEX], 1)`: discard REFLEX (fires AfterCardDiscarded),
    // draw 1, then auto-play the Sly REFLEX → its OnPlay draws 2.
    let _ = sts2_core::card_effects::discard_and_draw_with_hooks(&mut state, &[reflex], 1);
    let drawn = sentinels
        .iter()
        .filter(|u| state.player.hand.contains(u))
        .count();
    assert_eq!(
        drawn, 3,
        "count-draw (1) + REFLEX OnPlay (2) = 3; a 5 means the removed \
         after_card_discarded listener double-drew"
    );
}

/// MasterPlanner (Silent power) marks every player SKILL played as `Sly` for
/// the rest of the combat (C# `MasterPlannerPower.AfterCardPlayed` →
/// `CardCmd.ApplyKeyword(card, Sly)`), so a later active discard of that Skill
/// auto-plays it. The Rust power was a no-op stub, so a MasterPlanner-marked
/// DEFEND_SILENT discarded by Prepared/CalculatedGamble was not auto-played
/// (Silent sweep `DRAW_ORDER|PREPARED` seed 481: the auto-played DEFEND_SILENT's
/// 5 block went missing). Assert: a SKILL play marks the instance, an Attack
/// does not, and the marked instance auto-plays (gains its 5 block) when later
/// discarded through `discard_and_draw_with_hooks`.
#[test]
fn master_planner_marks_played_skills_sly_for_combat() {
    use sts2_core::hooks::CardCtx;
    install_pool();
    let (mut state, _euid) = fresh_state(CardId::MasterPlanner, 0, 0);
    state.player.current_hp = 70;
    state.player.max_hp = 70;
    let _ = state.init_player_creature();
    state.player.play.clear();
    // Apply the MasterPlanner power by playing the card.
    let _ = lookup(CardId::MasterPlanner).expect("registered")(&mut state, None);

    // A DEFEND_SILENT (Skill, +5 block) staged in hand, plus an Attack.
    let defend = sts2_core::CardUid(NonZeroU32::new(2).expect("nz"));
    state.cards.push(Card {
        uid: defend,
        card_id: CardId::DefendSilent,
        cost: 1,
        card_type: CardType::Skill,
        target_type: TargetType::Self_,
        base_block: 5,
        ..Card::pod_defaults()
    });
    let strike = sts2_core::CardUid(NonZeroU32::new(3).expect("nz"));
    state.cards.push(Card {
        uid: strike,
        card_id: CardId::StrikeSilent,
        cost: 1,
        card_type: CardType::Attack,
        target_type: TargetType::Enemy,
        base_damage: 6,
        ..Card::pod_defaults()
    });

    // Playing the SKILL marks it Sly for the combat; the Attack does not.
    sts2_core::hooks::dispatch_after_card_played(
        &mut state,
        &CardCtx {
            card_id: Some(CardId::DefendSilent),
            card_uid: Some(defend),
            card_tags: sts2_core::cards::CardTags::NONE,
            card_type: Some(CardType::Skill),
        },
    );
    sts2_core::hooks::dispatch_after_card_played(
        &mut state,
        &CardCtx {
            card_id: Some(CardId::StrikeSilent),
            card_uid: Some(strike),
            card_tags: sts2_core::cards::CardTags::NONE,
            card_type: Some(CardType::Attack),
        },
    );
    assert!(
        state.player.sly_this_combat.contains(&defend),
        "MasterPlanner marks the played SKILL Sly for the combat"
    );
    assert!(
        !state.player.sly_this_combat.contains(&strike),
        "MasterPlanner does NOT mark a played Attack"
    );

    // The marked DEFEND_SILENT, discarded via the active-discard helper,
    // auto-plays (Sly) and gains its 5 block.
    let block_before = state.player.block;
    state.player.hand.push(defend);
    let _ = sts2_core::card_effects::discard_and_draw_with_hooks(&mut state, &[defend], 0);
    assert_eq!(
        state.player.block,
        block_before + 5,
        "MasterPlanner-Sly DEFEND_SILENT auto-plays on discard and gains 5 block"
    );
}

/// Signed Strength drain that nets an existing instance to EXACTLY 0 must
/// REMOVE the power (C# `PowerModel.ShouldRemoveDueToAmount`, PowerModel.cs:413
/// — an `AllowNegative` attribute power is removed at == 0, kept while
/// negative). Regression for the Silent mid-fuzz `MONSTER_STATE|MALAISE
/// monsters[*].powers.len` divergence (seeds 911/1592/1838): Malaise draining a
/// STRENGTH(2) enemy by -2 left a phantom `STRENGTH(0)` in Rust while C#
/// removed it.
#[test]
fn signed_strength_drain_to_zero_removes_power_negative_keeps_it() {
    install_pool();
    let (mut state, euid) = fresh_state(CardId::Malaise, 0, 0);
    // Seed the enemy with STRENGTH(2).
    let sid = NonZeroU32::new(700).expect("nz");
    state.powers.push(Power {
        id: sid,
        kind: PowerKind::Strength,
        amount: 2,
        counter: 0,
        applier: None,
        skip_next_tick: false,
    });
    state.creatures[0].powers.push(PowerUid(sid));

    // -1 → STRENGTH(1): kept.
    super::helpers::apply_power_signed_to_creature(&mut state, euid, PowerKind::Strength, -1);
    assert_eq!(
        power_amount_on_creature(&state, euid, PowerKind::Strength),
        1
    );
    assert!(
        state.powers.iter().any(|p| p.kind == PowerKind::Strength),
        "STRENGTH(1) instance still present",
    );

    // -1 again → STRENGTH(0): REMOVED (exactly 0).
    super::helpers::apply_power_signed_to_creature(&mut state, euid, PowerKind::Strength, -1);
    assert_eq!(
        power_amount_on_creature(&state, euid, PowerKind::Strength),
        0
    );
    assert!(
        !state.powers.iter().any(|p| p.kind == PowerKind::Strength),
        "STRENGTH(0) must be removed, not left as a phantom 0-amount power",
    );
    assert!(
        !state.creatures[0].powers.iter().any(|u| u.0 == sid),
        "removed power's uid must be pruned from the creature's power list",
    );

    // Re-seed STRENGTH(1), drain -3 → STRENGTH(-2): a NEGATIVE result is KEPT.
    super::helpers::apply_power_signed_to_creature(&mut state, euid, PowerKind::Strength, 1);
    super::helpers::apply_power_signed_to_creature(&mut state, euid, PowerKind::Strength, -3);
    assert_eq!(
        power_amount_on_creature(&state, euid, PowerKind::Strength),
        -2,
        "AllowNegative power survives below 0",
    );
}

/// Malaise applies its two debuffs in C# order: `StrengthPower(-X)` FIRST
/// (`Malaise.cs:40`), then `WeakPower(X)` (`Malaise.cs:41`). The order is
/// only observable when the target has an Artifact stack — Artifact negates
/// (and consumes one stack on) the FIRST debuff applied. So a target with
/// Artifact(1) must keep WEAK and lose the Strength drain entirely.
/// Regression for the Silent fuzz `MONSTER_STATE|MALAISE` divergence (seed
/// 3330, Malaise+1 vs an Artifact(1) Chomper): Rust used to apply Weak
/// first, so Artifact wrongly negated Weak and STRENGTH(-X) survived.
#[test]
fn malaise_against_artifact_target_keeps_weak_strength_negated() {
    install_pool();
    let (mut state, euid) = fresh_state(CardId::Malaise, 0, 0);
    // X-cost: engine stamps energy_spent; upgraded adds +1 → amt = 4.
    let uid = *state.player.play.last().expect("Malaise in Play pile");
    state.cards[uid.0.get() as usize - 1].energy_spent = 3;
    state.cards[uid.0.get() as usize - 1].upgraded = true;

    // Seed the enemy with Artifact(1) — negates the first debuff applied.
    let aid = NonZeroU32::new(701).expect("nz");
    state.powers.push(Power {
        id: aid,
        kind: PowerKind::Artifact,
        amount: 1,
        counter: 0,
        applier: None,
        skip_next_tick: false,
    });
    state.creatures[0].powers.push(PowerUid(aid));

    let _ = lookup(CardId::Malaise).expect("registered")(&mut state, Some(euid));

    // Strength was applied FIRST → Artifact negates it; no STRENGTH instance.
    assert!(
        !state.powers.iter().any(|p| p.kind == PowerKind::Strength),
        "Strength is applied first and must be negated by Artifact (no STRENGTH on target)",
    );
    // Weak was applied SECOND → it survives at the full amount (4).
    assert_eq!(
        power_amount_on_creature(&state, euid, PowerKind::Weak),
        4,
        "Weak is applied after Strength and lands at the full X+1 amount",
    );
    // Exactly one Artifact stack consumed → Artifact(1) removed.
    assert!(
        !state.powers.iter().any(|p| p.kind == PowerKind::Artifact),
        "exactly one Artifact stack is consumed by the first (Strength) debuff",
    );
}

/// PiercingWail: stacks PiercingWail(6) on every alive enemy plus
/// Strength(-6). Verifies the stack-grew gate fires on first play.
#[test]
fn play_piercing_wail_stacks_pw_and_drains_strength() {
    install_pool();
    let (mut state, euid) = fresh_state(CardId::PiercingWail, 0, 0);
    let _ = lookup(CardId::PiercingWail).expect("registered")(&mut state, None);
    let pw = state
        .powers
        .iter()
        .find(|p| p.kind == PowerKind::PiercingWail)
        .expect("PiercingWail applied to enemy");
    assert_eq!(pw.amount, 6);
    let str_drain = state
        .powers
        .iter()
        .find(|p| p.kind == PowerKind::Strength)
        .expect("Strength drain applied");
    assert_eq!(str_drain.amount, -6);
    // Sanity: enemy uid carries both powers.
    let creature = state
        .creatures
        .iter()
        .find(|c| c.id == euid.0)
        .expect("enemy");
    assert_eq!(creature.powers.len(), 2);
}

/// EchoingSlash is a POWERED (`ValueProp.Move`) attack per C#
/// `EchoingSlash.cs` (`new DamageVar(10m, ValueProp.Move)`), so dealer
/// Strength (additive) + Weak and target Vulnerable (multiplicative) all
/// apply. Pin two enemies at 100 HP, stack Strength(+5) and Weak(2) on the
/// player and Vulnerable(2) on enemy A, then dispatch EchoingSlash:
/// enemy A takes `floor((10+5)*0.75*1.5)=16`, enemy B `floor((10+5)*0.75)=11`.
/// (The prior assertion of "base 10, no scaling" enshrined the Python-pin
/// `ValueProp.NONE` bug; the C# decomp is authoritative.)
#[test]
fn play_echoing_slash_applies_strength_weak_and_vulnerable() {
    use sts2_core::card_effects::apply_power_to_creature;
    install_pool();
    let (mut state, euid_a) = fresh_state(CardId::EchoingSlash, 10, 0);
    // Add a second enemy to lock in the "all alive enemies" iteration.
    let enemy_b_id = NonZeroU32::new(2).expect("nz");
    state.creatures.push(Creature {
        id: enemy_b_id,
        current_hp: 100,
        max_hp: 100,
        block: 0,
        powers: SmallVec::new(),
        species: Some(MonsterKind::Nibbit),
        intent: None,
        intent_history: IntentHistory::default(),
        monster_id: MonsterId("Nibbit"),
        ai: None,
    });
    let euid_b = CreatureUid(enemy_b_id);
    state.enemy_uids.push(euid_b);
    // Powered-channel modifiers apply on this MOVE-tagged AoE attack.
    apply_power_to_player(&mut state, PowerKind::Strength, 5);
    apply_power_to_player(&mut state, PowerKind::Weak, 2);
    apply_power_to_creature(&mut state, euid_a, PowerKind::Vulnerable, 2);

    let _ = lookup(CardId::EchoingSlash).expect("registered")(&mut state, None);

    let hp_a = state
        .creatures
        .iter()
        .find(|c| c.id == euid_a.0)
        .expect("enemy A")
        .current_hp;
    let hp_b = state
        .creatures
        .iter()
        .find(|c| c.id == euid_b.0)
        .expect("enemy B")
        .current_hp;
    assert_eq!(
        hp_a, 84,
        "Vulnerable enemy A: floor((10+5)*0.75*1.5)=16 damage"
    );
    assert_eq!(
        hp_b, 89,
        "Enemy B: floor((10+5)*0.75)=11 damage (Strength add + Weak scale)"
    );
}

