/// Bead `sts2-rs-m4kb`: HiddenDaggers discards up to 2 hand cards
/// (uniform-random subset via the chooser-collapse convention from
/// `fa8786e`), then spawns 2 Shivs. With 3 sentinel cards in hand
/// before play, expect: 2 discarded, 2 Shivs added → final hand
/// length = 3 - 2 + 2 = 3; discard pile gains 2; at least 2 hand
/// entries are Shivs.
/// Bead `sts2-rs-nightmare-select` — Nightmare's single-hand-card fast path:
/// C# `CardSelectCmd.FromHand`'s `cards.Count <= MinSelect` short-circuit
/// auto-applies to the lone hand card (no prompt). Playing Nightmare applies 3
/// stacks of `PowerKind::Nightmare` with `Power::counter` stashing the lone
/// hand uid; the clones now fire on the PRE-DRAW power dispatch
/// (`dispatch_before_hand_draw_powers`, C# `NightmarePower.BeforeHandDraw`),
/// cloning the stashed card 3 times into hand and removing the power.
#[test]
fn nightmare_one_hand_card_auto_picks_and_clones_three_before_hand_draw() {
    use sts2_core::hooks::dispatch_before_hand_draw_powers;
    install_pool();
    let (mut state, _) = fresh_state(CardId::Nightmare, 0, 0);
    // Seed a single hand card to be the auto-pick target. The fresh_state
    // helper pushes the Nightmare card itself with uid=1 into Play; we add a
    // Strike with uid=2 into Hand. With exactly one hand card the FromHand
    // select auto-applies (no prompt).
    let strike_uid = NonZeroU32::new(2).expect("nz");
    state.cards.push(Card {
        uid: sts2_core::CardUid(strike_uid),
        card_id: CardId::StrikeSilent,
        cost: 1,
        card_type: CardType::Attack,
        target_type: TargetType::Enemy,
        upgraded: false,
        base_damage: 6,
        base_block: 0,
        ..Card::pod_defaults()
    });
    state.player.hand.push(sts2_core::CardUid(strike_uid));

    // Play Nightmare → 3 stacks of the power, counter = 2 (strike uid),
    // and NO pending choice (the lone hand card auto-applies).
    let _ = lookup(CardId::Nightmare).expect("registered")(&mut state, None);
    assert!(
        state.pending_choice.is_none(),
        "one hand card auto-applies; no select opens"
    );
    let power = state
        .powers
        .iter()
        .find(|p| p.kind == PowerKind::Nightmare)
        .expect("Nightmare power applied");
    assert_eq!(power.amount, 3, "3 stacks applied");
    assert_eq!(power.counter, 2, "stash equals picked uid (strike=2)");

    // Hand still has the original Strike (no immediate clones; the
    // deferral path is the pre-draw power dispatch).
    assert_eq!(
        state.player.hand.len(),
        1,
        "play body must NOT immediately clone; deferral via before-hand-draw"
    );

    // Fire the PRE-DRAW power dispatch (where Nightmare now lives, so the
    // clones precede the natural turn draw).
    dispatch_before_hand_draw_powers(&mut state);

    // 3 clones of Strike appended to hand, original Strike still
    // there: 4 cards total.
    assert_eq!(state.player.hand.len(), 4, "3 clones + original");
    // Power instance removed.
    assert!(
        state.powers.iter().all(|p| p.kind != PowerKind::Nightmare),
        "Nightmare power must be removed after firing"
    );
}

/// v0.107.1 Nightmare strips the Affliction from the copies it makes
/// (`NightmarePower.SetSelectedCard` clones + `CardCmd.ClearAffliction`).
/// The ORIGINAL selected hand card keeps its affliction; the 3 next-turn
/// clones are affliction-free.
#[test]
fn nightmare_clones_drop_the_selected_cards_affliction() {
    use sts2_core::card_afflictions::{CardAffliction, CardAfflictionKind};
    use sts2_core::hooks::dispatch_before_hand_draw_powers;
    install_pool();
    let (mut state, _) = fresh_state(CardId::Nightmare, 0, 0);
    // A single afflicted hand card → auto-pick target.
    let strike_uid = NonZeroU32::new(2).expect("nz");
    let mut strike = Card {
        uid: sts2_core::CardUid(strike_uid),
        card_id: CardId::StrikeSilent,
        cost: 1,
        card_type: CardType::Attack,
        target_type: TargetType::Enemy,
        upgraded: false,
        base_damage: 6,
        base_block: 0,
        ..Card::pod_defaults()
    };
    assert!(
        strike.set_affliction(CardAffliction {
            kind: CardAfflictionKind::Bound,
            stacks: 1,
            applied_exhaust: false,
        }),
        "Bound afflicts an Attack card"
    );
    state.cards.push(strike);
    state.player.hand.push(sts2_core::CardUid(strike_uid));

    let _ = lookup(CardId::Nightmare).expect("registered")(&mut state, None);
    dispatch_before_hand_draw_powers(&mut state);

    assert_eq!(state.player.hand.len(), 4, "3 clones + original");
    // Original (uid 2) keeps its affliction.
    let original = state
        .cards
        .iter()
        .find(|c| c.uid == sts2_core::CardUid(strike_uid))
        .expect("original card present");
    assert!(
        original.affliction.is_some(),
        "the selected hand card keeps its own affliction"
    );
    // Every clone (StrikeSilent in hand other than uid 2) is affliction-free.
    let clones: Vec<_> = state
        .player
        .hand
        .iter()
        .filter(|u| **u != sts2_core::CardUid(strike_uid))
        .filter_map(|u| state.cards.iter().find(|c| c.uid == *u))
        .collect();
    assert_eq!(clones.len(), 3, "exactly 3 clones");
    for clone in clones {
        assert_eq!(clone.card_id, CardId::StrikeSilent);
        assert!(
            clone.affliction.is_none(),
            "Nightmare clones must have their affliction stripped"
        );
    }
}

/// Bead `sts2-rs-nightmare-select` — Nightmare with 2+ hand cards: C#
/// `CardSelectCmd.FromHand(prefs(1), filter: null)` opens a single-pick
/// `CloneChosenCardNextTurn` select over the whole hand (no auto-pick).
/// Resolving the choice applies the power and stashes the CHOSEN card's uid
/// into its `counter` (not blindly the first) — the whole-run parity fix
/// (Silent sweep RP53 `combat/state/enemies_hp` cs=[33] rs=[27]). The pre-draw
/// power dispatch then clones the chosen card 3 times.
///
/// GH #364 A1: this test previously asserted the power was applied *up front*,
/// pinning the very ordering bug the issue reports. C# `Nightmare.cs:32` awaits
/// the select and applies at `:44`, so a mid-play snapshot must carry NO
/// Nightmare power.
#[test]
fn nightmare_two_hand_cards_opens_select_and_clones_chosen() {
    use sts2_core::hooks::dispatch_before_hand_draw_powers;
    install_pool();
    let (mut state, _) = fresh_state(CardId::Nightmare, 0, 0);
    // Two distinct, observable hand cards: Strike (uid 2), Defend (uid 3).
    let strike_uid = NonZeroU32::new(2).expect("nz");
    state.cards.push(Card {
        uid: sts2_core::CardUid(strike_uid),
        card_id: CardId::StrikeSilent,
        cost: 1,
        card_type: CardType::Attack,
        target_type: TargetType::Enemy,
        upgraded: false,
        base_damage: 6,
        base_block: 0,
        ..Card::pod_defaults()
    });
    state.player.hand.push(sts2_core::CardUid(strike_uid));
    let defend_uid = NonZeroU32::new(3).expect("nz");
    state.cards.push(Card {
        uid: sts2_core::CardUid(defend_uid),
        card_id: CardId::DefendSilent,
        cost: 1,
        card_type: CardType::Skill,
        target_type: TargetType::Self_,
        upgraded: false,
        base_damage: 0,
        base_block: 5,
        ..Card::pod_defaults()
    });
    state.player.hand.push(sts2_core::CardUid(defend_uid));

    // Play Nightmare → single-pick choice opens, power NOT yet applied.
    let _ = lookup(CardId::Nightmare).expect("registered")(&mut state, None);
    let pc = state
        .pending_choice
        .as_ref()
        .expect("Nightmare opens a choice with 2+ hand cards");
    assert_eq!(pc.kind, sts2_core::ChoiceKind::CloneChosenCardNextTurn);
    assert_eq!(
        pc.options.len(),
        2,
        "both hand cards are options, hand order"
    );
    assert_eq!(pc.options[0].card_uid, Some(sts2_core::CardUid(strike_uid)));
    assert_eq!(pc.options[1].card_uid, Some(sts2_core::CardUid(defend_uid)));
    // GH #364 A1: the `Apply` trails the select in C# (`Nightmare.cs:44`), so
    // while the choice is open the player carries NO Nightmare power. The apply
    // rides on the choice's `post_effect` instead.
    assert!(
        state.powers.iter().all(|p| p.kind != PowerKind::Nightmare),
        "no Nightmare power while the select is still open"
    );
    assert_eq!(
        pc.post_effect,
        Some(sts2_core::PostChoiceEffect::ApplyPlayerPower(
            PowerKind::Nightmare,
            3
        )),
        "the deferred Apply rides on the choice"
    );

    // Pick option 1 (the SECOND card, Defend) — applies the power, stashes Defend.
    let selection: SmallVec<[u8; 4]> = [1u8].into_iter().collect();
    let res = sts2_core::apply(&mut state, sts2_core::Action::ResolveChoice { selection });
    assert_eq!(res, sts2_core::StepResult::Advanced);
    assert!(state.pending_choice.is_none(), "choice cleared on resolve");
    let power = state
        .powers
        .iter()
        .find(|p| p.kind == PowerKind::Nightmare)
        .expect("power applied by the post-choice effect on resolve");
    assert_eq!(power.amount, 3, "3 stacks, applied after the select");
    assert_eq!(
        power.counter, 3,
        "stash equals CHOSEN uid (defend=3), not first"
    );

    // Fire the pre-draw power dispatch → 3 Defend clones into hand.
    dispatch_before_hand_draw_powers(&mut state);
    // Original Strike + Defend (2) plus 3 Defend clones = 5.
    assert_eq!(
        state.player.hand.len(),
        5,
        "3 clones of the chosen card + 2 originals"
    );
    let clone_count = state
        .player
        .hand
        .iter()
        .filter(|&&u| state.cards[u.0.get() as usize - 1].card_id == CardId::DefendSilent)
        .count();
    assert_eq!(
        clone_count, 4,
        "original Defend + 3 clones (chosen card cloned)"
    );
    assert!(
        state.powers.iter().all(|p| p.kind != PowerKind::Nightmare),
        "Nightmare power removed after firing"
    );
}

/// C# `NightmarePower.SetSelectedCard` stores `card.CreateClone()` at select
/// time and `BeforeHandDraw` clones that snapshot (NightmarePower.cs:41-63,
/// both builds; `MutableClone` deep-copies the enchantment state). So a change
/// to the original after the select (here an upgrade and a spent Glam-style
/// combat var) does not reach the next-turn copies. Rust cloned the live card
/// at BeforeHandDraw, so a played Glam original's used bit leaked into the
/// clones (act23 Ironclad v0.111.0 seed 8180 act 3, step 980).
#[test]
fn nightmare_clones_the_select_time_snapshot_not_the_live_card() {
    use sts2_core::cards::VarKey;
    use sts2_core::hooks::dispatch_before_hand_draw_powers;
    install_pool();
    let (mut state, _) = fresh_state(CardId::Nightmare, 0, 0);
    let mut uids = Vec::new();
    for (raw, id) in [(2u32, CardId::StrikeSilent), (3, CardId::DefendSilent)] {
        let uid = sts2_core::CardUid(NonZeroU32::new(raw).expect("nz"));
        state.cards.push(Card {
            uid,
            card_id: id,
            cost: 1,
            ..Card::pod_defaults()
        });
        state.player.hand.push(uid);
        uids.push(uid);
    }
    let _ = lookup(CardId::Nightmare).expect("registered")(&mut state, None);
    let selection: SmallVec<[u8; 4]> = [0u8].into_iter().collect();
    let _ = sts2_core::apply(&mut state, sts2_core::Action::ResolveChoice { selection });

    // The original changes after the select.
    let original = &mut state.cards[uids[0].0.get() as usize - 1];
    assert_eq!(original.card_id, CardId::StrikeSilent);
    original.upgraded = true;
    original.set_combat_var(VarKey::EnchantmentUsed, 1);

    dispatch_before_hand_draw_powers(&mut state);
    let clones: Vec<&Card> = state
        .player
        .hand
        .iter()
        .filter(|u| !uids.contains(u))
        .map(|u| &state.cards[u.0.get() as usize - 1])
        .collect();
    assert_eq!(clones.len(), 3);
    for c in clones {
        assert_eq!(c.card_id, CardId::StrikeSilent);
        assert!(!c.upgraded, "the clone is the select-time snapshot");
        assert_eq!(c.combat_var(VarKey::EnchantmentUsed), 0);
    }
}

/// GH #364 A2 — a Nightmare power whose selected card is unrecoverable still
/// EXPIRES. The live world wire cannot carry the card identity:
/// `SimStateExtractor.cs:730-742` emits `(int)dv.BaseValue` and the "Card"
/// dynamic var is a `StringVar` whose `BaseValue` is hardcoded `0m`
/// (`StringVar.cs:7`), so reconstruction yields `counter == 0`. The prior code
/// skipped such an instance entirely — including its removal — so the mirror
/// carried a Nightmare power that could neither fire nor expire (the 4 "sticky
/// at end_turn" records in live Silent seed 1000). C# `NightmarePower.cs:51`
/// calls `PowerCmd.Remove(this)` unconditionally, outside any card-null check.
#[test]
fn nightmare_with_an_unrecoverable_card_still_expires_on_hand_draw() {
    use sts2_core::hooks::dispatch_before_hand_draw_powers;
    install_pool();
    let (mut state, _) = fresh_state(CardId::Nightmare, 0, 0);
    // A hand card, so a stuck power would be visible against a stable hand.
    let strike_uid = NonZeroU32::new(2).expect("nz");
    state.cards.push(Card {
        uid: sts2_core::CardUid(strike_uid),
        card_id: CardId::StrikeSilent,
        cost: 1,
        card_type: CardType::Attack,
        target_type: TargetType::Enemy,
        upgraded: false,
        base_damage: 6,
        base_block: 0,
        ..Card::pod_defaults()
    });
    state.player.hand.push(sts2_core::CardUid(strike_uid));

    // A wire-reconstructed Nightmare: 3 stacks, counter == 0 ("not set").
    let pid = NonZeroU32::new(900).expect("nz");
    state.powers.push(Power {
        id: pid,
        kind: PowerKind::Nightmare,
        amount: 3,
        counter: 0,
        applier: None,
        skip_next_tick: false,
    });
    let puid = sts2_core::PowerUid(pid);
    state.player.powers.push(puid);
    if let Some(cuid) = state.player.creature_uid {
        if let Some(c) = state.creatures.iter_mut().find(|c| c.id == cuid.0) {
            c.powers.push(puid);
        }
    }

    dispatch_before_hand_draw_powers(&mut state);

    // No clones — the card identity is simply not knowable.
    assert_eq!(
        state.player.hand.len(),
        1,
        "an unrecoverable selection clones nothing"
    );
    // But the power is gone, exactly as C# removes it unconditionally.
    assert!(
        state.powers.iter().all(|p| p.kind != PowerKind::Nightmare),
        "the power must expire even with no recoverable card"
    );
    assert!(
        state.player.powers.iter().all(|u| u.0 != pid),
        "and be unlinked from the player's power list"
    );
    for c in &state.creatures {
        assert!(
            c.powers.iter().all(|u| u.0 != pid),
            "and from every creature's mirror list"
        );
    }
}

/// Bead `sts2-rs-1xmxp`: with > 2 hand cards, HiddenDaggers opens a
/// `DiscardFromHand` player choice (exactly 2) instead of a random
/// discard. The 2 Shivs come AFTER the discard resolves (C# awaits the
/// select and the discard before `Shiv.CreateInHand`), so they are never
/// discard candidates; resolving the choice discards the 2 chosen
/// sentinels and then spawns the Shivs.
#[test]
fn play_hidden_daggers_opens_discard_choice_then_resolves() {
    install_pool();
    // The deferred Shivs are built through the core card factory.
    sts2_core::register_card_factory(crate::cards::spec_index::card_pod_from_id);
    let (mut state, _) = fresh_state(CardId::HiddenDaggers, 0, 0);
    // Push 3 sentinel hand cards (uids 2..=4 — fresh_state used uid 1
    // for the play-pile card).
    let mut sentinel_uids: SmallVec<[sts2_core::CardUid; 8]> = SmallVec::new();
    for slot in 2_u32..=4 {
        let uid = sts2_core::CardUid(NonZeroU32::new(slot).expect("nz"));
        state.cards.push(Card {
            uid,
            card_id: CardId::StrikeSilent,
            cost: 1,
            card_type: CardType::Attack,
            target_type: TargetType::Enemy,
            upgraded: false,
            base_damage: 6,
            base_block: 0,
            ..Card::pod_defaults()
        });
        state.player.hand.push(uid);
        sentinel_uids.push(uid);
    }
    assert_eq!(state.player.hand.len(), 3, "precondition: 3 in hand");
    let r = lookup(CardId::HiddenDaggers).expect("registered")(&mut state, None);
    assert_eq!(r, EffectResult::Resolved);

    // A discard choice over exactly the 3 sentinels (not the Shivs) is
    // open; nothing discarded yet; the 2 Shivs are already in hand.
    let pc = state
        .pending_choice
        .as_ref()
        .expect("discard choice opened");
    assert_eq!(pc.kind, sts2_core::ChoiceKind::DiscardFromHand);
    assert_eq!((pc.min_select, pc.max_select), (2, 2), "discard exactly 2");
    assert_eq!(pc.options.len(), 3, "choose among the 3 sentinels");
    for opt in &pc.options {
        assert!(
            sentinel_uids.contains(&opt.card_uid.expect("hand card")),
            "Shivs must not be offered as discard candidates",
        );
    }
    assert!(state.player.discard.is_empty(), "no discard until resolved");
    assert_eq!(
        state.player.hand.len(),
        3,
        "the Shivs wait for the discard to resolve",
    );

    // Resolve: discard the first two sentinels (selection [0, 1]).
    let selection: smallvec::SmallVec<[u8; 4]> = [0u8, 1].into_iter().collect();
    let res = sts2_core::apply(&mut state, sts2_core::Action::ResolveChoice { selection });
    assert_eq!(res, sts2_core::StepResult::Advanced);
    assert!(state.pending_choice.is_none(), "choice cleared");
    // The two CHOSEN sentinels are discarded; the third is kept. (The
    // played HiddenDaggers card also flushes to discard after the
    // choice resolves — engine behavior — so we assert on the chosen
    // sentinels specifically rather than the raw discard count.)
    assert!(state.player.discard.contains(&sentinel_uids[0]), "chose s0");
    assert!(state.player.discard.contains(&sentinel_uids[1]), "chose s1");
    assert!(
        !state.player.discard.contains(&sentinel_uids[2]),
        "unchosen sentinel stays in hand",
    );
    // Hand: the unchosen sentinel + the 2 freshly-spawned Shivs.
    assert_eq!(state.player.hand.len(), 3, "1 sentinel + 2 Shivs remain");
    assert!(state.player.hand.contains(&sentinel_uids[2]));
    let shivs_in_hand = state
        .player
        .hand
        .iter()
        .filter(|u| {
            state
                .cards
                .iter()
                .find(|c| c.uid == **u)
                .is_some_and(|c| c.card_id == CardId::Shiv)
        })
        .count();
    assert_eq!(shivs_in_hand, 2, "both Shivs retained in hand");
}

/// GH #1054 (Silent-1001 act-3 `hand_costs` split): a Sly card discarded
/// by HiddenDaggers auto-plays inside C# `CardCmd.Discard`, before
/// `Shiv.CreateInHand` runs. So Reflex's draw lands in hand BEFORE the
/// two Shivs. Rust spawned the Shivs when the choice opened, putting them
/// ahead of Reflex's draw.
#[test]
fn play_hidden_daggers_sly_draw_lands_before_the_shivs() {
    install_pool();
    // The deferred Shivs are built through the core card factory.
    sts2_core::register_card_factory(crate::cards::spec_index::card_pod_from_id);
    sts2_core::card_effects::register_card_sly(CardId::Reflex);
    let (mut state, _) = fresh_state(CardId::HiddenDaggers, 0, 0);
    let push = |state: &mut CombatState, slot: u32, card_id: CardId, card_type: CardType| {
        let uid = sts2_core::CardUid(NonZeroU32::new(slot).expect("nz"));
        state.cards.push(Card {
            uid,
            card_id,
            cost: 1,
            card_type,
            target_type: TargetType::Self_,
            ..Card::pod_defaults()
        });
        uid
    };
    let reflex = push(&mut state, 2, CardId::Reflex, CardType::Skill);
    let keep = push(&mut state, 3, CardId::DefendSilent, CardType::Skill);
    let other = push(&mut state, 4, CardId::DefendSilent, CardType::Skill);
    state.player.hand.extend([reflex, keep, other]);
    let drawn_a = push(&mut state, 5, CardId::StrikeSilent, CardType::Attack);
    let drawn_b = push(&mut state, 6, CardId::StrikeSilent, CardType::Attack);
    state.player.draw.extend([drawn_b, drawn_a]);

    let _ = lookup(CardId::HiddenDaggers).expect("registered")(&mut state, None);
    // Discard Reflex and `other` (option order = hand order).
    let selection: smallvec::SmallVec<[u8; 4]> = [0u8, 2].into_iter().collect();
    let _ = sts2_core::apply(&mut state, sts2_core::Action::ResolveChoice { selection });

    let ids: Vec<CardId> = state
        .player
        .hand
        .iter()
        .map(|u| state.cards[u.0.get() as usize - 1].card_id)
        .collect();
    assert_eq!(
        ids,
        [
            CardId::DefendSilent,
            CardId::StrikeSilent,
            CardId::StrikeSilent,
            CardId::Shiv,
            CardId::Shiv,
        ],
        "Reflex's 2 draws come before HiddenDaggers' Shivs",
    );
}

/// Bead `sts2-rs-1xmxp`: with ≤ 2 hand cards there is no real choice
/// (all must be discarded), so HiddenDaggers auto-discards without a
/// prompt and still spawns 2 Shivs.
#[test]
fn play_hidden_daggers_one_card_auto_discards_no_prompt() {
    install_pool();
    let (mut state, _) = fresh_state(CardId::HiddenDaggers, 0, 0);
    let uid = sts2_core::CardUid(NonZeroU32::new(2).expect("nz"));
    state.cards.push(Card {
        uid,
        card_id: CardId::StrikeSilent,
        cost: 1,
        card_type: CardType::Attack,
        target_type: TargetType::Enemy,
        upgraded: false,
        base_damage: 6,
        base_block: 0,
        ..Card::pod_defaults()
    });
    state.player.hand.push(uid);
    let r = lookup(CardId::HiddenDaggers).expect("registered")(&mut state, None);
    assert_eq!(r, EffectResult::Resolved);
    assert!(state.pending_choice.is_none(), "single card → no prompt");
    assert_eq!(state.player.discard.len(), 1, "1 discarded");
    assert!(
        state.player.discard.contains(&uid),
        "the sentinel discarded"
    );
    let shivs = state
        .player
        .hand
        .iter()
        .filter(|u| {
            state
                .cards
                .iter()
                .find(|c| c.uid == **u)
                .is_some_and(|c| c.card_id == CardId::Shiv)
        })
        .count();
    assert_eq!(shivs, 2, "2 Shivs spawned");
    // Base HiddenDaggers — Shivs are NOT upgraded.
    for &uid in &state.player.hand {
        let idx = uid.0.get() as usize - 1;
        let card = &state.cards[idx];
        if card.card_id == CardId::Shiv {
            assert!(!card.upgraded, "base Shiv (not upgraded)");
            assert_eq!(card.base_damage, 4, "base Shiv = 4 damage");
        }
    }
}

/// Silent fuzz seed 24: HiddenDaggers' AUTO-discard branch (hand ≤ 2, no
/// prompt) must route through the Sly-aware discard so a discarded Tactician
/// (Sly) auto-plays and grants its +1 energy — C# `CardCmd.Discard` fires the
/// Sly trigger; the prior raw `discard_hand_card` loop dropped it (energy stuck
/// at 0 vs C#'s 1).
#[test]
fn play_hidden_daggers_auto_discard_fires_sly_tactician_energy() {
    install_pool();
    // `install_pool` registers effect handlers but not the SLY keyword set
    // (the full content install's `install_sly_keywords` does, which the live
    // parity harness runs); register it here so `card_sly(Tactician)` is true.
    sts2_core::card_effects::register_card_sly(CardId::Tactician);
    let (mut state, _) = fresh_state(CardId::HiddenDaggers, 0, 0);
    let uid = sts2_core::CardUid(NonZeroU32::new(2).expect("nz"));
    state.cards.push(Card {
        uid,
        card_id: CardId::Tactician,
        cost: 3,
        card_type: CardType::Skill,
        target_type: TargetType::Self_,
        upgraded: false,
        base_damage: 0,
        base_block: 0,
        ..Card::pod_defaults()
    });
    state.player.hand.push(uid);
    state.player.energy = 0;
    let r = lookup(CardId::HiddenDaggers).expect("registered")(&mut state, None);
    assert_eq!(r, EffectResult::Resolved);
    assert!(state.pending_choice.is_none(), "single card → no prompt");
    assert_eq!(
        state.player.energy, 1,
        "discarded Tactician (Sly) auto-plays → +1 energy"
    );
}

/// Bead `sts2-rs-dw4ha`: upgraded HiddenDaggers spawns Shiv+
/// (`upgraded=true`, base_damage 6) per C# `HiddenDaggers.cs:OnPlay`
/// looping `CardCmd.Upgrade(item)` over each spawned Shiv when
/// `IsUpgraded`.
#[test]
fn play_hidden_daggers_upgraded_spawns_two_upgraded_shivs() {
    install_pool();
    let (mut state, _) = fresh_state(CardId::HiddenDaggers, 0, 0);
    state.cards[0].upgraded = true; // upgrade HiddenDaggers itself
    let uid = sts2_core::CardUid(NonZeroU32::new(2).expect("nz"));
    state.cards.push(Card {
        uid,
        card_id: CardId::StrikeSilent,
        cost: 1,
        card_type: CardType::Attack,
        target_type: TargetType::Enemy,
        upgraded: false,
        base_damage: 6,
        base_block: 0,
        ..Card::pod_defaults()
    });
    state.player.hand.push(uid);
    let r = lookup(CardId::HiddenDaggers).expect("registered")(&mut state, None);
    assert_eq!(r, EffectResult::Resolved);
    let mut upgraded_shivs = 0;
    for &uid in &state.player.hand {
        let idx = uid.0.get() as usize - 1;
        let card = &state.cards[idx];
        if card.card_id == CardId::Shiv {
            assert!(card.upgraded, "spawned Shiv is upgraded");
            assert_eq!(card.base_damage, 6, "Shiv+ deals 6 damage");
            upgraded_shivs += 1;
        }
    }
    assert_eq!(upgraded_shivs, 2);
}

/// Bead `sts2-rs-5tetc` follow-up: EchoingSlash rewaves once per enemy KILLED
/// by a wave (C# `attackCount += WasTargetKilled count`). A low-HP enemy dies
/// in wave 1, triggering a second AoE wave that the survivor also takes — so
/// the survivor is hit twice. (The kill count must track per-target deaths,
/// not the net alive-enemy delta, so a death that spawns new enemies still
/// counts — see the handler comment; that spawn case is covered by the
/// Silent fuzz sweep seed 19.)
#[test]
fn echoing_slash_rewaves_on_kill() {
    install_pool();
    let (mut state, dying) = fresh_state(CardId::EchoingSlash, 10, 0);
    // The first enemy dies to a single 10-damage wave.
    if let Some(c) = state.creatures.iter_mut().find(|c| c.id == dying.0) {
        c.current_hp = 5;
    }
    // A high-HP survivor that should eat TWO waves (initial + kill rewave).
    let survivor_id = NonZeroU32::new(2).expect("nz");
    state.creatures.push(Creature {
        id: survivor_id,
        current_hp: 100,
        max_hp: 100,
        block: 0,
        powers: SmallVec::new(),
        species: Some(MonsterKind::Nibbit),
        intent: None,
        intent_history: IntentHistory::default(),
        monster_id: MonsterId("Nibbit"),
        ai: None,
    });
    state.enemy_uids.push(CreatureUid(survivor_id));

    let _ = lookup(CardId::EchoingSlash).expect("registered")(&mut state, None);

    let survivor_hp = state
        .creatures
        .iter()
        .find(|c| c.id == survivor_id)
        .map(|c| c.current_hp)
        .expect("survivor");
    assert_eq!(
        survivor_hp, 80,
        "survivor takes 2 waves (10+10) — the kill of the low-HP enemy rewaves"
    );
}
